'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='permineralization'?'Etymology Explorer: https://etymologyexplorer.com/word/English/permineralization':w==='perry'?'Oxford Learner’s Dictionaries: https://www.oxfordlearnersdictionaries.com/us/definition/english/perry':w==='perth'?'National Museum of Australia: https://www.nma.gov.au/defining-moments/resources/founding-of-perth':w==='pet name'?'Etymonline: https://www.etymonline.com/word/pet':w==='pet peeve'?'Etymonline: https://www.etymonline.com/word/pet%20peeve':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('permeable','Permeable comes from Late Latin permeabilis, “capable of being passed through,” from permeare, “to pass through.”',C('permeable.s1','可渗透的','The filter uses a permeable membrane that lets water molecules pass while trapping larger particles.','过滤器使用可渗透膜，让水分子通过，同时截留较大的颗粒。','The filter uses a permeable membrane / that lets water molecules pass / while trapping larger particles.','permeable 形容液体或气体能够穿过的材料。','水分子可以穿过膜，而较大颗粒被截留。'),M('The membrane was permeable, so it completely prevented water from passing through it.','The membrane was permeable, so water could pass through it while larger particles were trapped.','permeable 表示可通过；完全阻止水通过恰好相反。','meaning'),[q('What can pass through the filter membrane?','water molecules','all larger particles','the filter housing','水分子可穿过膜，较大颗粒则被截留。'),q('What does permeable describe?','a material that allows something to pass through','a material that blocks every substance','a material that dissolves every particle','permeable 描述允许物质通过的材料。',1,'meaning'),q('Which surface is permeable to rain?','a porous path that lets water soak into the ground','a sealed roof that sheds all water','a sheet of metal with no openings','多孔路面允许雨水渗入地下。',1,'context'),q('What does Latin permeare mean?','to pass through','to hold back','to measure twice','permeare 表示“通过、穿过”。',1,'word-formation')]);
P('permeance','Permeance is formed from permeate with -ance; it names permeability generally and, in magnetism, the ease with which magnetic flux is established.',[C('permeance.s1','磁导','The engineer increased the core’s permeance by choosing a material that allowed magnetic flux to pass readily.','工程师选用容易传导磁通的材料，提高了磁芯的磁导。','The engineer increased the core’s permeance / by choosing a material / that allowed magnetic flux to pass readily.','磁学中的 permeance 表示磁路建立磁通的容易程度。','材料更容易传导磁通，磁导随之增加。'),C('permeance.s2','弥漫性；渗透性质','The permeance of the scent through the curtains became obvious when the bakery opened next door.','隔壁面包店开门后，香味穿过窗帘弥漫进来的性质变得明显。','The permeance of the scent through the curtains / became obvious / when the bakery opened next door.','一般用法中 permeance 可指某物渗透或弥散的性质。','香味从邻店穿过窗帘进入房间。')],M('The core had high permeance, yet the engineer chose it because it stopped magnetic flux from entering the circuit.','The core had high permeance, so magnetic flux could be established in the circuit with little resistance.','磁导高表示磁通容易建立，不是阻止磁通进入。','meaning'),[q('Why did the engineer choose that core material?','it let magnetic flux pass readily','it blocked every magnetic field','it made the circuit waterproof','该材料容易传导磁通，因此磁导较高。',1,'context'),q('What is permeance in a magnetic circuit?','how readily magnetic flux is established','the amount of electrical charge stored in a battery','the resistance of a liquid filter to water','磁学 permeance 指磁通在磁路中建立的容易程度。',1,'meaning'),q('What happened to the bakery scent?','it spread through the curtains into the room','it stayed sealed inside the oven','it turned the curtains into a magnetic core','香味穿过窗帘弥散开来。',2,'context'),q('Which word is the base of permeance?','permeate','permission','perpendicular','permeance 由 permeate 加名词后缀构成。',1,'word-formation')]);
P('permeate','Permeate comes from Latin permeare, “to pass through,” from per, “through,” and meare, “to pass”; it can describe physical penetration or widespread influence.',[C('permeate.s1','渗透；渗入','Warm cooking oil began to permeate the paper towel beneath the fried food.','温热的食用油开始渗进炸物下面的纸巾。','Warm cooking oil began to permeate the paper towel / beneath the fried food.','permeate 作物理义时表示缓慢穿过材料的各部分。','油从纸巾一侧逐渐渗入。'),C('permeate.s2','弥漫；遍布；充满','A sense of relief permeated the clinic after the missing child was found safe.','失踪儿童平安找到后，宽慰的情绪弥漫在诊所里。','A sense of relief permeated the clinic / after the missing child was found safe.','permeate 也可表示某种情绪或特征遍布一个地方或群体。','诊所里的每个人都感到宽慰。')],M('The cooking oil permeated the towel, but remained only on its surface and entered none of its fibers.','The cooking oil permeated the towel by soaking into its fibers.','permeate 表示渗入各部分；仅停留在表面与此相反。','meaning'),[q('What did the warm oil do to the paper towel?','soaked into its fibers','froze above it without touching it','changed into a magnetic field','油渗入了纸巾纤维。',1,'context'),q('What permeated the clinic after the child returned?','a sense of relief','an unrelated legal rule','water from a broken filter','孩子平安找到后，宽慰的情绪充满诊所。',2,'context'),q('Which sentence uses permeate figuratively?','Suspicion permeated the team after the data disappeared.','Rain permeated the soil through its pores.','The valve permitted water to enter.','怀疑在团队中普遍弥漫，属于比喻用法。',2,'meaning'),q('What does permeate mean?','pass through or spread throughout','stop at the outer surface','make an official request','permeate 表示穿过或遍布。',1,'meaning')]);
P('permineralization','Permineralization is a geological formation from per- and mineralization; it describes groundwater minerals filling spaces within buried remains and preserving structure.',C('permineralization.s1','渗矿化','Groundwater deposited silica in the open spaces of the buried wood, a process called permineralization.','地下水把二氧化硅沉积在埋藏木材的空隙中，这一过程称为渗矿化。','Groundwater deposited silica / in the open spaces of the buried wood / a process called permineralization.','permineralization 是地下水携带矿物进入骨骼、木材或贝壳内部空隙并沉积的化石保存过程。','矿物填充木材内部空隙，结构得以保存。'),M('The specimen underwent permineralization when groundwater removed every mineral from its internal spaces and left them empty.','The specimen underwent permineralization when groundwater deposited minerals in its internal spaces.','渗矿化是矿物沉积并填充内部空隙，不是把矿物全部移走。','meaning'),[q('Where did the silica collect in the buried wood?','in its open internal spaces','only on the museum label','inside the groundwater container','二氧化硅沉积在木材内部的空隙中。'),q('What does permineralization preserve?','internal structure as minerals fill spaces in buried remains','only the color of an animal’s fur','a fossil by dissolving every hard part','该过程以矿物填充空隙，有助于保存内部结构。',1,'meaning'),q('Which specimen most directly illustrates permineralization?','buried wood with mineral deposits in its pores','a fresh leaf dried on a table','a shell painted with mineral-colored ink','木材孔隙被矿物沉积填充，是渗矿化实例。',1,'context'),q('Which components form the technical term?','per- and mineralization','permission and ability','perpendicular and section','该术语由 per- 与 mineralization 构成。',1,'word-formation')]);
P('permissibility','Permissibility is formed from permissible and -ity; it names whether an action is acceptable under a particular rule.',C('permissibility.s1','可允许性','The review board discussed the permissibility of sharing the anonymized records under the privacy policy.','审查委员会讨论了根据隐私政策分享匿名记录是否可允许。','The review board discussed the permissibility / of sharing the anonymized records / under the privacy policy.','permissibility 指某行为是否符合规定而可被允许。','委员会依据隐私政策作出可否判断。'),M('The board confirmed the permissibility of sharing the records, then ruled that the same sharing was prohibited by its policy.','The board confirmed that sharing the anonymized records was permissible under its policy.','permissibility 指行为可被允许；“确认允许后又认定禁止”自相矛盾。','meaning'),[q('What did the board evaluate?','whether sharing anonymized records was allowed','whether the records could be made magnetic','whether the policy contained a paragraph','委员会评估分享记录是否符合规定。'),q('What does permissibility mean?','the quality of being acceptable under a rule','the act of asking someone to repeat a sentence','a measure of magnetic flux','permissibility 指依规则判断是否可允许。',1,'meaning'),q('Which question concerns permissibility?','May researchers reuse these records under the consent form?','How many pages are in the report?','Which color is the archive folder?','研究者能否根据同意书重用记录，是可允许性问题。',1,'context'),q('What suffix turns permissible into permissibility?','-ity','-ly','-ness','-ity 将形容词构成抽象名词。',1,'word-formation')]);
P('permissible','Permissible comes through Old French from Medieval Latin permissibilis, based on Latin permittere, “let pass or allow.”',C('permissible.s1','可允许的；在限度内的','Only a small amount of personal browsing is permissible on the office network during breaks.','休息时间里，办公网络只允许少量个人浏览。','Only a small amount of personal browsing / is permissible / on the office network during breaks.','permissible 表示按规则可接受、可被允许的。','规则允许少量而非无限制的个人浏览。'),M('The policy says personal browsing is permissible only in small amounts, so employees may use the network for unlimited shopping all day.','The policy says only a small amount of personal browsing is permissible, mainly during breaks.','许可范围有限，不包括整天无限制购物。','meaning'),[q('When is personal browsing allowed?','in small amounts during breaks','without limits throughout the workday','only after the network is disconnected','规定只允许休息时少量个人浏览。',1,'context'),q('What does permissible mean?','acceptable according to a rule','required in every situation','impossible to carry out','permissible 指规则允许或认可的。',1,'meaning'),q('Which expense is permissible under a strict travel policy?','a meal within the stated daily limit','a luxury purchase above the limit','a private vacation charged to the company','在规定每日限额内的餐费符合许可规则。',1,'context'),q('Which source verb is behind permissible?','permittere, “allow or let pass”','perpendere, “weigh carefully”','permeare, “pass through”','permissible 与拉丁语 permittere“允许”有关。',1,'word-formation')]);
P('permissibly','Permissibly is the adverb from permissible, meaning “in a way that is allowed by the relevant rule.”',C('permissibly.s1','在许可范围内','The archivist permissibly shared the public catalog, but kept restricted medical files sealed.','档案员在许可范围内分享了公开目录，同时封存了受限医疗档案。','The archivist permissibly shared the public catalog / but kept restricted medical files sealed.','permissibly 修饰动作，说明该动作符合规定而被允许。','只分享公开目录，受限档案仍受保护。'),M('The clerk permissibly opened confidential files without authorization and in direct violation of the access rule.','The clerk permissibly opened only the public records covered by the access rule.','违反访问规则的未授权行为不能称为 permissibly。','context'),[q('What did the archivist share permissibly?','the public catalog','restricted medical files','a sealed personnel record','档案员只分享了可公开的目录。',1,'context'),q('What does permissibly mean?','in a way the rules allow','in a way that ignores every rule','in a way that happens by accident','permissibly 表示“在许可范围内”。',1,'meaning'),q('Which action was done permissibly?','using an image after receiving the required license','copying a protected report without consent','entering a locked office without a key','获得许可后使用图片符合规定。',1,'context'),q('What is permissibly derived from?','permissible plus -ly','permission plus -ment','permeable plus -ity','-ly 将 permissible 变成副词 permissibly。',1,'word-formation')]);
P('permission','Permission came through Old French from Latin permissio, from permittere, “to let pass or allow”; it is the act of allowing someone to do something.',C('permission.s1','允许；许可','Nora asked the museum for permission to photograph the sculpture before the gallery closed.','画廊关闭前，诺拉向博物馆请求拍摄雕塑的许可。','Nora asked the museum for permission / to photograph the sculpture / before the gallery closed.','permission 是允许某人做某事的授权或行为。','她先请求授权，再拍摄雕塑。'),M('Nora photographed the sculpture without permission, yet the guard confirmed that she had received formal approval beforehand.','Nora photographed the sculpture after receiving permission from the museum.','未经许可和已获正式批准互相矛盾。','meaning'),[q('What did Nora request permission to do?','photograph the sculpture','move the sculpture to another museum','close the gallery permanently','诺拉请求拍摄雕塑的许可。'),q('What is permission?','authorization to do something','a written account of a crime','the ability of water to cross a membrane','permission 指允许某人采取行动。',1,'meaning'),q('Which action requires permission in the example?','taking a photograph inside the gallery','looking at the sculpture from the doorway','reading the museum’s public hours','诺拉必须先获得拍摄授权。',1,'context'),q('What is the relation between permission and permit?','permission is the noun related to the verb permit','permission is the plural of permit','permit is the past tense of permission','permission 是与 permit 相关的名词。',1,'word-formation')]);
P('permissive','Permissive comes from Medieval Latin permissivus, “allowing to pass”; modern senses describe tolerant rules or something that grants permission.',[C('permissive.s1','放任的；过分宽容的','The permissive classroom rule allowed students to interrupt one another, so the teacher replaced it with clear turn-taking guidelines.','这条过于宽松的课堂规则允许学生互相打断，因此老师换成了明确的轮流发言规定。','The permissive classroom rule allowed students to interrupt one another / so the teacher replaced it / with clear turn-taking guidelines.','permissive 可形容允许过多行为、缺少限制的规则或态度。','规则让学生随意打断，限制不足。'),C('permissive.s2','许可的；准许的','The permit contains a permissive clause allowing the research team to collect water samples at the site.','许可证中有一项授权条款，允许研究团队在该地点采集水样。','The permit contains a permissive clause / allowing the research team / to collect water samples at the site.','正式用法中 permissive 可表示给予许可或授权。','条款明确授权采样。')],M('The school adopted a permissive rule that strictly prohibited every student from speaking during group work.','The school adopted a permissive rule that allowed students to discuss ideas freely during group work.','permissive 表示宽松、允许；严格禁止交谈与宽松规则相反。','meaning'),[q('Why did the teacher replace the classroom rule?','it let students interrupt one another','it required orderly turn-taking','it prohibited every student from speaking','原规则过于宽松，学生可以互相打断。',1,'context'),q('What does the permit’s permissive clause do?','it authorizes the team to collect samples','it prohibits all research at the site','it transfers ownership of the river','条款给予研究团队采样许可。',2,'context'),q('Which policy is permissive?','one that allows broad freedom with few restrictions','one that bans every exception','one that has no written conditions at all','宽松政策允许较大自由、限制较少。',1,'meaning'),q('Which meaning of permissive fits a permit clause?','granting permission','showing extreme suspicion','measuring a magnetic circuit','条款授权采样，属于“准许的”这一义项。',2,'meaning')]);
P('permissiveness','Permissiveness is formed from permissive and -ness; it means a quality of allowing considerable freedom of behaviour.',C('permissiveness.s1','放任；宽容','The report linked the school’s permissiveness to unclear boundaries rather than to the students’ lack of ability.','报告把学校的放任态度归因于界限不清，而不是学生能力不足。','The report linked the school’s permissiveness / to unclear boundaries / rather than to the students’ lack of ability.','permissiveness 指允许很多行为、不严格设限的特质。','报告指出问题是规则界限太宽松。'),M('The report described the school’s permissiveness as a policy that allowed no exceptions and punished every minor mistake.','The report described the school’s permissiveness as a policy that allowed wide freedom with few limits.','permissiveness 是较宽松、少限制，不是严厉地处罚所有小错。','meaning'),[q('What did the report blame for unclear boundaries?','the school’s permissiveness','the students’ mathematical ability','the color of the classroom walls','报告将界限不清归因于学校过度宽松。'),q('What does permissiveness describe?','a tendency to allow broad freedom','a strict refusal to allow exceptions','a formal request for authorization','permissiveness 指允许较大自由的态度。',1,'meaning'),q('Which setting shows permissiveness?','a club lets members set their own schedules and rules','a club checks every minute and bans all changes','a club has no members or activities','成员可自行安排日程、限制很少，体现宽松。',1,'context'),q('What suffix forms permissiveness?','-ness','-ible','-ate','-ness 将 permissive 构成抽象名词。',1,'word-formation')]);
P('permit','Permit comes from Old French and Latin permittere, “let pass or allow”; as a verb it allows or makes possible, and as a noun it is official written authorization.',[C('permit.s1','允许；准许','The guide permits visitors to take notes, but asks them not to touch the paintings.','导览规定允许游客做笔记，但请他们不要触摸画作。','The guide permits visitors to take notes / but asks them / not to touch the paintings.','permit 作及物动词可表示允许某人做某事。','做笔记获准，触摸画作不获准。'),C('permit.s2','（条件）允许；使成为可能','Weather permitting, the crew will repair the roof before the next storm arrives.','如果天气允许，施工队会在下一场风暴到来前修理屋顶。','Weather permitting / the crew will repair the roof / before the next storm arrives.','permit 可指条件使某事成为可能；weather permitting 是常见独立结构。','维修计划以天气条件许可为前提。'),C('permit.s3','许可证；执照','The researcher displayed her collection permit at the entrance before carrying the samples out of the reserve.','研究人员把采集许可证出示在保护区入口，才将样本带出。','The researcher displayed her collection permit / at the entrance / before carrying the samples out of the reserve.','permit 作名词指官方书面许可或执照。','文件授权她采集并带走样本。')],M('The researcher carried samples out of the reserve with no permit, although the guard verified that the document authorized her collection.','The researcher carried samples out of the reserve after showing the permit that authorized collection.','原句同时说无许可证和已有授权文件，前后矛盾；permit 是许可文件。','meaning'),[q('What may visitors do under the guide’s rule?','take notes','touch the paintings','remove a painting from the gallery','游客可以做笔记，但不能触摸画作。',1,'context'),q('What does “weather permitting” mean?','if the weather makes it possible','even if the weather makes it impossible','only when the roof is already repaired','该短语表示“如果天气条件允许”。',2,'context'),q('What did the researcher show at the reserve entrance?','an official collection permit','a museum membership card','a map of the roof repairs','她出示了采集许可证。',3,'context'),q('Which sentence uses permit as a noun?','You need a permit to collect samples here.','The rules permit visitors to take notes.','Weather permitting, work will begin tomorrow.','第一句中 permit 是许可证名词。',3,'meaning')]);
P('permutation','Permutation came from Latin permutatio, from permutare, “change thoroughly”; it is an arrangement produced by reordering, especially where order matters.',[C('permutation.s1','排列','The code has six possible permutations because changing the order of the three symbols creates a different code.','这个密码有六种可能的排列，因为三个符号的顺序一变，密码就不同。','The code has six possible permutations / because changing the order / of the three symbols creates a different code.','数学中的 permutation 是对象的一种排列，且顺序不同就视为不同排列。','符号顺序改变会产生不同密码。'),C('permutation.s2','变化形式','The redesigned schedule is one permutation of the original plan, with the same tasks arranged in a new order.','重新设计的日程是原计划的一种变化形式，任务相同但顺序不同。','The redesigned schedule is one permutation of the original plan / with the same tasks / arranged in a new order.','permutation 也可指若干可能重组方式中的一种变化形式。','任务不变，仅重新编排。')],M('The code’s permutation stayed identical after the symbols were reordered, even though order was what defined the code.','Reordering the symbols produced a different permutation of the code.','若顺序决定密码，改变顺序就会形成不同排列。','meaning'),[q('Why are there six code permutations?','different orders of the three symbols make different codes','the code contains six unrelated symbols','the order never changes the code','三个符号有六种不同顺序排列。',1,'context'),q('What distinguishes permutations from combinations?','the order of the items matters','the items must all be identical','permutations cannot be counted','排列中顺序会影响结果。',1,'meaning'),q('What changed in the redesigned schedule?','the tasks were arranged in a new order','the tasks were replaced by unrelated ones','the schedule was canceled entirely','日程中的任务相同，但重新安排了顺序。',2,'context'),q('What did Latin permutare mean?','change thoroughly or exchange','allow someone to proceed','hang at a right angle','permutare 表示彻底改变或交换。',1,'word-formation')]);
P('pernicious','Pernicious came through Old French from Latin perniciosus, “destructive,” from pernicies, “ruin or death”; it describes gradual or far-reaching harm.',C('pernicious.s1','有害的；危害深远的','The report warned that a pernicious rumor could erode trust across the small community long after it was disproved.','报告警告，一则有害谣言即使被证伪很久后，仍可能侵蚀小社区的信任。','The report warned / that a pernicious rumor could erode trust / long after it was disproved.','pernicious 指逐渐造成严重、广泛或难以察觉的伤害。','谣言在被证伪后仍侵蚀信任，影响持久。'),M('The report called the rumor pernicious because it was harmless, disappeared immediately, and had no effect on trust.','The report called the rumor pernicious because it continued to damage trust even after it was disproved.','pernicious 表示造成严重或持久伤害，题干的无害且无影响与此相反。','meaning'),[q('What lasting effect could the rumor have?','it could erode trust in the community','it would improve every relationship','it would stop the weather from changing','谣言可能长期侵蚀社区信任。'),q('What does pernicious mean?','harmful in a serious or gradual way','mildly inconvenient for a moment','officially allowed by a rule','pernicious 描述严重、渐进的危害。',1,'meaning'),q('Which influence is pernicious?','a misleading message that slowly undermines public health','a brief delay that causes no harm','a clear notice that prevents an accident','误导信息逐渐损害公共健康，具有危害性。',1,'context'),q('What does Latin pernicies mean?','ruin or destruction','a fair arrangement','permission to enter','pernicies 表示毁灭或灾祸。',1,'word-formation')]);
P('perpendicular','Perpendicular came from Latin perpendicularis, “vertical like a plumb line,” from perpendiculum, “plumb line”; it means meeting at a right angle.',C('perpendicular.s1','垂直的；成直角的','The carpenter checked that the new shelf bracket was perpendicular to the wall before tightening the screws.','木匠拧紧螺丝前，先检查新支架是否与墙面垂直。','The carpenter checked / that the new shelf bracket was perpendicular to the wall / before tightening the screws.','perpendicular 描述两条线或两个平面以90度相交。','支架与墙面成直角。'),M('The carpenter said the bracket was perpendicular to the wall, although it met the wall at an acute angle of thirty degrees.','The carpenter said the bracket was perpendicular to the wall because it met the wall at a right angle.','垂直要求90度，30度是锐角。','measurement'),[q('What did the carpenter check?','the bracket met the wall at a right angle','the bracket ran parallel to the floor for ten meters','the wall was made of permeable material','木匠检查支架与墙面是否成直角。'),q('How many degrees is a perpendicular intersection?','90 degrees','30 degrees','180 degrees','垂直相交构成90度角。',1,'measurement'),q('Which lines are perpendicular?','one vertical line and one horizontal line crossing','two horizontal lines that never meet','two lines crossing at a 30-degree angle','一横一竖相交形成直角。',1,'meaning'),q('What instrument lies behind the source word perpendiculum?','a plumb line','a magnetic core','a water filter','perpendiculum 指铅垂线。',1,'word-formation')]);
P('perpetrate','Perpetrate comes from Latin perpetratus, the participle of perpetrare, “perform or accomplish”; English especially uses it for committing a crime or harmful act.',C('perpetrate.s1','犯下；实施','Investigators found that the fraud was perpetrated by a manager who altered the invoices over several months.','调查人员发现，这起欺诈是由一名经理实施的，他连续数月篡改发票。','Investigators found / that the fraud was perpetrated by a manager / who altered the invoices over several months.','perpetrate 常指实施应受谴责的行为，尤其是罪行或欺诈。','经理持续篡改发票，实施了欺诈。'),M('The report said the manager perpetrated the fraud, but also stated that he never took part in it and had no involvement.','The report said the manager perpetrated the fraud by altering invoices over several months.','perpetrate 表示实施某事；说他实施欺诈又完全未参与，前后冲突。','meaning'),[q('What did investigators discover?','a manager altered invoices over several months','the invoices were never changed','the museum had issued a photography permit','调查发现经理数月篡改发票。',1,'context'),q('What does perpetrate usually mean?','commit or carry out a blameworthy act','prevent a crime from happening','request official permission','perpetrate 常表示犯下或实施不法行为。',1,'meaning'),q('Which action could someone perpetrate?','a deliberate fraud against customers','a routine task completed honestly','a harmless walk through a public park','蓄意欺诈是可被实施的恶行。',1,'context'),q('What did the Latin source perpetrare mean?','perform or accomplish','pass through a membrane','measure a right angle','perpetrare 表示实施或完成。',1,'word-formation')]);
P('perpetual','Perpetual came through French from Latin perpetualis and perpetuus, “continuous”; it means lasting forever or happening repeatedly without relief.',[C('perpetual.s1','永久的；永恒的','The constitution protects the perpetual right of residents to access the public shoreline.','宪法保障居民永久享有进入公共海岸线的权利。','The constitution protects the perpetual right / of residents / to access the public shoreline.','perpetual 可表示持续很久、无终止的。','权利被描述为永久有效。'),C('perpetual.s2','没完没了的；连续不断的','The staff grew tired of the perpetual alarms that sounded every time the faulty sensor detected steam.','每当故障传感器检测到蒸汽就响起没完没了的警报，员工们对此感到厌烦。','The staff grew tired / of the perpetual alarms / that sounded whenever the faulty sensor detected steam.','perpetual 也可形容反复发生、令人厌烦的事情。','警报一再响起，使员工厌倦。')],M('The staff called the alarm perpetual even though it rang once and never sounded again.','The staff called the alarm perpetual because it sounded repeatedly whenever the sensor detected steam.','反复响起才符合这里“没完没了”的 perpetual 义。','meaning'),[q('What right does the constitution protect?','residents’ continuing access to the shoreline','a one-time visit to a private garden','a permit to collect unrelated samples','宪法保障居民永久进入公共海岸线。',1,'context'),q('Why were staff tired of the alarms?','they sounded repeatedly whenever the sensor detected steam','they had never sounded before','they were used only once during a test','传感器每次检测到蒸汽都会触发警报。',2,'context'),q('Which meaning fits “perpetual motion”?','motion imagined to continue without end','a single movement followed by rest','motion that is forbidden by a permit','perpetual 表示持续无休。',1,'meaning'),q('Which word is the Latin adjective source of perpetual?','perpetuus','pernicies','permeabilis','perpetual 来自拉丁语 perpetuus。',1,'word-formation')]);
P('perpetuate','Perpetuate came from Latin perpetuare, “make perpetual,” from perpetuus, “continuous”; it means keep something going indefinitely.',C('perpetuate.s1','使永久化；使继续存在','The museum added oral histories to perpetuate the memory of the workers who built the railway.','博物馆加入口述史料，以长久保存修建铁路工人的记忆。','The museum added oral histories / to perpetuate the memory / of the workers who built the railway.','perpetuate 指使记忆、传统、信念或状况持续存在。','记录口述史是为了让工人的记忆延续。'),M('The museum recorded the workers’ stories to perpetuate their memory, then erased every recording the next day.','The museum recorded and preserved the workers’ stories to perpetuate their memory.','永久保存记忆与第二天删除所有记录相冲突。','meaning'),[q('Why did the museum collect oral histories?','to keep the workers’ memory alive','to cancel the railway project','to issue a parking permit','口述史用来延续工人的记忆。'),q('What does perpetuate mean?','cause something to continue or last','stop something immediately','make something perpendicular','perpetuate 表示使某事持续存在。',1,'meaning'),q('Which action could perpetuate an unfair custom?','teaching it to every new generation without question','ending it through a new law','recording evidence to challenge it','不加质疑地代代传授会让不公平习俗延续。',1,'context'),q('Which word underlies perpetuate?','perpetual','permissible','perpendicular','perpetuate 与 perpetual 同源。',1,'word-formation')]);
P('perpetuation','Perpetuation comes from Medieval Latin perpetuatio, from perpetuare, “make continuous”; it is the continued existence or deliberate preservation of something.',C('perpetuation.s1','延续；使长存','The committee warned that repeating the false statistic would lead to the perpetuation of a harmful myth.','委员会警告，反复传播错误统计数字会导致有害迷思延续。','The committee warned / that repeating the false statistic / would lead to the perpetuation of a harmful myth.','perpetuation 指某习俗、问题或记忆持续存在或被不断保存。','不断重复错误数据会让迷思继续传播。'),M('The campaign ended the perpetuation of the rumor by repeating it in every new public notice.','The campaign ended the perpetuation of the rumor by correcting it and asking outlets to stop repeating it.','重复传播谣言会让它延续，而非终止。','meaning'),[q('What could repeated false statistics cause?','the continued spread of a harmful myth','the immediate disappearance of every rumor','a right angle in the committee room','反复传播错误数字可能让有害迷思延续。'),q('What does perpetuation name?','the continuation or preservation of something','a single request for permission','the act of forming a permutation','perpetuation 指延续或保存某事。',1,'meaning'),q('Which action risks perpetuation of a stereotype?','repeating it in new reports without checking it','removing it from training materials','publishing evidence that disproves it','未经核实地在新报告中重复刻板印象，会使其延续。',1,'context'),q('What is perpetuation related to?','perpetuate','perpendicular','permeable','perpetuation 是 perpetuate 的名词形式。',1,'word-formation')]);
P('perplex','Perplex comes from Latin perplexus, “involved or entangled”; English first used it for being puzzled and also for making a problem more intricate.',[C('perplex.s1','使困惑；把……弄糊涂','The two conflicting dates perplexed the archivist, who could not tell which record was genuine.','两个相互矛盾的日期让档案员困惑不已，她无法判断哪份记录是真的。','The two conflicting dates perplexed the archivist / who could not tell / which record was genuine.','perplex 可指使人困惑、难以理解。','日期冲突导致她无法判断记录真伪。'),C('perplex.s2','使复杂化；使更费解','Adding three unrelated rules only perplexed the simple permit process.','额外加入三条无关规定只会让简单的许可流程更加复杂难懂。','Adding three unrelated rules / only perplexed the simple permit process.','perplex 也可表示使问题或流程更复杂、更难理解。','无关规则增加了流程的复杂性。')],M('The conflicting dates perplexed the archivist, so she immediately knew which record was genuine without checking anything.','The conflicting dates perplexed the archivist, so she checked the sources before deciding which record was genuine.','困惑意味着难以判断；若她立刻确定答案，便不符合这里的反应。','meaning'),[q('Why was the archivist perplexed?','two records gave conflicting dates','both records had identical dates and sources','the permit process was canceled','记录日期冲突，让档案员难以判断。',1,'context'),q('What did the extra rules do to the permit process?','made it harder to understand','made it shorter and clearer','allowed every application automatically','无关规则让流程更复杂、更费解。',2,'context'),q('Which sentence uses perplex meaning “make intricate”?','The added exception perplexed an otherwise simple contract.','The clear label perplexed no reader.','She asked permission to enter.','额外例外使合同复杂化，符合此义。',2,'meaning'),q('What image is behind Latin perplexus?','being entangled or involved','passing cleanly through a filter','standing at a right angle','perplexus 带有缠绕、纠结之意。',1,'word-formation')]);
P('perplexing','Perplexing is the -ing adjective from perplex; it describes facts or a question that cause confusion because they do not fit together.',C('perplexing.s1','令人费解的','The most perplexing clue was a dry footprint inside a room that had no windows or doors.','最令人费解的线索，是一间没有门窗的房间里竟有一个干燥的脚印。','The most perplexing clue / was a dry footprint / inside a room that had no windows or doors.','perplexing 描述令人困惑、难以解释的事物。','封闭房间里的干脚印与环境不相符。'),M('The clue was perplexing, but it matched the investigator’s prediction exactly and required no explanation.','The clue was perplexing because a dry footprint appeared inside a sealed room.','若线索完全符合预测且无需解释，就不令人费解。','meaning'),[q('What made the clue perplexing?','a dry footprint appeared in a sealed room','the room had a clearly marked exit','the floor was wet after cleaning','封闭房间中的干脚印难以解释。'),q('What does perplexing mean?','causing confusion because details do not fit together','easy to understand and fully expected','formally allowed by a written rule','perplexing 表示令人费解。',1,'meaning'),q('Which result is perplexing?','a sealed file contains a report dated next week','a signed form bears today’s date','a permit has the same number as its receipt','密封文件中出现下周日期的报告，令人费解。',1,'context'),q('Which word does perplexing come from?','perplex','perpetual','permissive','perplexing 是 perplex 的 -ing 形容词。',1,'word-formation')]);
P('perplexity','Perplexity came through Old French and Latin from perplexus, “confused or entangled”; it means bewilderment or a puzzling matter.',[C('perplexity.s1','困惑','The curator stared in perplexity at two labels that gave different dates for the same painting.','看到两张标签给同一幅画标出不同年代，馆长困惑地盯着它们。','The curator stared in perplexity / at two labels / that gave different dates for the same painting.','perplexity 作名词可指无法理解或判断时的困惑感。','同一幅画出现两个不同年代，引起困惑。'),C('perplexity.s2','难题','The missing bridge plans became a perplexity for engineers trying to calculate the river’s original width.','桥梁图纸遗失成了工程师的一道难题，他们正试图计算河流原来的宽度。','The missing bridge plans became a perplexity / for engineers / trying to calculate the river’s original width.','perplexity 也可指令人费解的难题或复杂状况。','没有图纸使计算工作无法顺利进行。')],M('The labels caused perplexity, but both clearly listed the same date and left the curator with no uncertainty.','The labels caused perplexity because they gave conflicting dates for the painting.','perplexity 是困惑；如果标签一致且毫无疑问，就不会产生困惑。','meaning'),[q('Why did the curator stare in perplexity?','two labels gave different dates for one painting','both labels clearly showed the same date','the painting had no label at all','两张标签给出不同年代，让馆长困惑。',1,'context'),q('What became a perplexity for the engineers?','the missing bridge plans','a signed permit already on file','a clear photograph of the river','图纸遗失使工程师遇到难题。',2,'context'),q('Which meaning fits “to my perplexity”?','to my confusion','to my permission','to my relief','该短语表示“令我困惑的是”。',1,'meaning'),q('What image lies behind Latin perplexus?','being tangled or involved','passing through a filter','standing at a right angle','perplexus 带有缠绕、纠结的含义。',1,'word-formation')]);
P('perquisite','Perquisite came from Medieval Latin perquisitum, “thing sought or gained”; it means an extra benefit attached to a job beyond regular pay.',C('perquisite.s1','额外补贴；职务特权','A company car was a perquisite of the director’s position, separate from her monthly salary.','公司配车是这位主管职位附带的额外福利，与月薪分开。','A company car was a perquisite of the director’s position / separate from her monthly salary.','perquisite 指随职位或工作附带的额外收益或特权。','配车是职位福利，不是工资本身。'),M('The contract listed a company car as a perquisite, then stated that it was not an extra benefit and came with no job-related privilege.','The contract listed a company car as a perquisite, an extra benefit attached to the director’s role.','perquisite 是工作附带的额外收益；合同不能同时说它毫非额外福利。','meaning'),[q('What was the director’s perquisite?','a company car in addition to salary','a reduction in her job title','a one-time grocery bill','公司配车是职位附带福利。'),q('What does perquisite mean in a job offer?','an extra benefit beyond regular wages','the basic salary before deductions','a duty that every employee must perform','perquisite 指工资之外的额外福利。',1,'meaning'),q('Which item could be a perquisite of a senior post?','use of a company apartment','the employee’s required monthly paycheck','a public notice about office hours','公司公寓使用权可作为高阶职位福利。',1,'context'),q('What did Latin perquisitum mean?','a thing sought or gained','a thing forbidden by law','a line measured at a right angle','perquisitum 表示寻得或获得的东西。',1,'word-formation')]);
P('perry','Perry is a fermented pear drink; the word came through Old French pere from Latin pirum, “pear.”',C('perry.s1','梨酒','The orchard fermented its ripe pears into perry and served a small glass with the autumn meal.','果园把成熟的梨发酵制成梨酒，并在秋季餐食时端上一小杯。','The orchard fermented its ripe pears into perry / and served a small glass / with the autumn meal.','perry 是由梨汁发酵制成、类似苹果酒的饮料。','原料和发酵过程表明是梨酒。'),M('The orchard made perry by fermenting apple juice, although the recipe used no pears at all.','The orchard made perry by fermenting pear juice.','perry 是梨制发酵饮料；苹果汁发酵所得通常称 cider。','meaning'),[q('What fruit did the orchard ferment?','ripe pears','green apples only','grapes from a vineyard','梨经发酵制成 perry。'),q('What is perry?','a fermented drink made from pears','a clear juice served before fermentation','a permit for entering an orchard','perry 是由梨制成的发酵饮料。',1,'meaning'),q('Which drink would be perry?','a cider-like drink made from fermented pear juice','a fermented drink made only from apples','a sweet tea flavored with pear but not fermented','发酵梨汁饮料符合 perry 的定义。',1,'context'),q('What does Latin pirum mean?','pear','apple','plum','拉丁语 pirum 指梨。',1,'word-formation')]);
P('persecute','Persecute came through Old French from Latin persecutus, “follow or pursue”; it means cruelly target someone over time, often for beliefs, or continually annoy.',[C('persecute.s1','迫害','The regime persecuted journalists who reported on election fraud, repeatedly jailing and threatening them.','该政权迫害报道选举舞弊的记者，反复将他们关押并威胁。','The regime persecuted journalists / who reported on election fraud / repeatedly jailing and threatening them.','persecute 可指长期因宗教、政治立场或身份而残酷对待某人或群体。','记者因报道政治问题而遭持续打压。'),C('persecute.s2','纠缠；烦扰','My little brother persecuted me with questions about the game until I agreed to explain the rules.','弟弟不停追问我游戏的事，直到我答应解释规则。','My little brother persecuted me with questions about the game / until I agreed / to explain the rules.','较口语的用法中，persecute 也可表示持续纠缠或烦扰某人。','反复追问直到对方让步。')],M('The regime persecuted the journalists by protecting them from arrest and allowing them to report freely.','The regime persecuted the journalists by repeatedly arresting and threatening them for their reporting.','保护记者并允许自由报道不是迫害；迫害包含持续敌对对待。','meaning'),[q('Why did the regime target the journalists?','they reported on election fraud','they asked about a board game','they requested a parking space','记者因报道选举舞弊遭到打压。',1,'context'),q('How did the younger brother persecute the speaker?','he kept asking questions until she agreed to explain','he stopped asking as soon as she answered once','he wrote a report about election rules','他反复追问，纠缠姐姐解释游戏规则。',2,'context'),q('Which action is persecution?','repeatedly punishing a group for its religious beliefs','criticizing one article once and politely','asking permission to enter a museum','因信仰反复惩罚群体属于迫害。',1,'meaning'),q('What is the original image in Latin persecutus?','following or pursuing','allowing something to pass','staying at a right angle','persecutus 原有“追随、追捕”之意。',1,'word-formation')]);
P('persecution','Persecution comes through Old French from Latin persecutio, from persequi, “pursue”; it is sustained hostility or punishment directed at a person or group.',C('persecution.s1','迫害','The archive contains letters describing the persecution of families who were forced to leave because of their religion.','档案中保存着书信，记述了因宗教信仰而被迫离乡的家庭所遭受的迫害。','The archive contains letters / describing the persecution of families / forced to leave because of their religion.','persecution 指针对个人或群体的持续敌意、惩罚或压迫。','家庭因信仰遭到强迫迁离。'),M('The archive called it persecution, although the families faced no hostility, punishment, or pressure to leave.','The archive called it persecution because families were punished and forced to leave for their religious beliefs.','迫害包含持续敌对或惩罚；没有任何压迫就不构成此义。','meaning'),[q('Why were the families forced to leave?','their religious beliefs led to sustained hostility','they received a company-car benefit','they asked to join a festival','家庭因宗教信仰而遭到迫害。',1,'context'),q('What is persecution?','continued hostile treatment or punishment of a person or group','a single neutral disagreement about a schedule','a written permission to visit an archive','persecution 指持续迫害或惩罚。',1,'meaning'),q('Which record documents persecution?','letters describing a group being repeatedly punished for its beliefs','a permit approving a community event','a list of staff salaries','信件记录群体因信仰反复受罚，属于迫害史料。',1,'context'),q('Which verb is the base of persecution?','persecute','perplex','permeate','persecution 是 persecute 的名词形式。',1,'word-formation')]);
P('perseverance','Perseverance came through Old French from Latin perseverantia, “steadfastness”; it means continued effort despite difficulty or the quality of not giving up.',[C('perseverance.s1','毅力；坚持不懈','Her perseverance through months of failed experiments finally produced a reliable vaccine candidate.','尽管数月实验失败，她仍坚持不懈，最终获得了可靠的候选疫苗。','Her perseverance through months of failed experiments / finally produced / a reliable vaccine candidate.','perseverance 指在困难中持续努力直至接近目标的毅力。','多次失败后仍继续实验。'),C('perseverance.s2','忍耐；不屈不挠','The slow restoration demanded perseverance, since each damaged page required careful cleaning by hand.','修复进展缓慢，要求极大的耐心，因为每一页受损书页都需要手工仔细清洁。','The slow restoration demanded perseverance / since each damaged page / required careful cleaning by hand.','perseverance 也指面对缓慢、艰难工作仍不放弃的品质。','修复工作细致缓慢，必须坚持。')],M('The team showed perseverance by abandoning the project after the first failed experiment and refusing to try again.','The team showed perseverance by continuing experiments after early failures.','面对困难持续努力才是 perseverance；一次失败后立即放弃并非坚持。','meaning'),[q('What did the researcher’s perseverance achieve?','a reliable vaccine candidate after repeated experiments','a company car without completing the research','a decision to stop after the first attempt','持续实验最终获得可靠候选疫苗。',1,'context'),q('What made the page restoration demand perseverance?','each page needed slow, careful hand cleaning','the pages were already fully restored','the team could clean every page instantly','每页都要手工细致修复，工作缓慢而艰难。',2,'context'),q('What is perseverance?','steady effort that continues despite obstacles','an extra benefit attached to a job','a sudden decision to quit','perseverance 是面对困难仍持续努力。',1,'meaning'),q('Which older Latin noun is the source of perseverance?','perseverantia','pernicies','perquīsītum','perseverance 来自拉丁语 perseverantia。',1,'word-formation')]);
P('persevere','Persevere came from Latin perseverare, “continue steadfastly”; it means keep trying to achieve something despite difficulty.',C('persevere.s1','坚持；不屈不挠','Although the first two grant applications were rejected, the small laboratory decided to persevere and submit a stronger proposal.','尽管前两份拨款申请都被拒绝，这家小实验室仍决定坚持下去，提交更有力的方案。','Although the first two grant applications were rejected / the small laboratory decided to persevere / and submit a stronger proposal.','persevere 后常接 in/with，表示遇到阻力仍继续努力。','被拒后仍准备改进并再次申请。'),M('The laboratory persevered by abandoning the proposal after one rejection and never making another attempt.','The laboratory persevered by revising its proposal and applying again after the rejection.','继续改进再尝试才是坚持；彻底放弃不是 persevere。','meaning'),[q('What did the laboratory do after two rejections?','it planned to revise and submit a stronger proposal','it closed immediately without reviewing the feedback','it received a company car','实验室决定改进方案后继续申请。'),q('When does someone persevere?','when they keep trying despite setbacks','when they succeed on the first try and stop','when they refuse to begin any task','persevere 指遇到挫折仍继续尝试。',1,'meaning'),q('Which sentence uses persevere naturally?','She persevered with the difficult course until she passed.','She persevered the door open with a metal bar.','The sunset persevered red across the sky.','persevere with the course 表示坚持完成困难课程。',1,'context'),q('What does Latin perseverare suggest?','continuing with steadfastness','granting permission','changing an arrangement','perseverare 表示坚定地继续。',1,'word-formation')]);
P('persist','Persist came from Latin persistere, “continue steadfastly,” from per-, “thoroughly,” and sistere, “stand”; it can mean insist, continue to exist, or keep asserting.',[C('persist.s1','坚持；执意','Despite the committee’s objections, Mara persisted in asking for a public audit.','尽管委员会反对，玛拉仍坚持要求进行公开审计。','Despite the committee’s objections / Mara persisted in asking / for a public audit.','persist in doing 表示不顾反对坚持做某事。','她在明确反对声中继续提出要求。'),C('persist.s2','继续存在；持续','A faint smell of smoke persisted in the hallway long after the fire had been extinguished.','火被扑灭很久后，走廊里仍残留着淡淡的烟味。','A faint smell of smoke persisted in the hallway / long after the fire / had been extinguished.','persist 也可指状况或现象在预期之后继续存在。','烟味在火熄灭后仍持续。'),C('persist.s3','坚称；反复说','Even after the map proved him wrong, the guide persisted that the trail crossed the northern ridge.','即使地图证明他错了，导游仍坚称小路穿过北侧山脊。','Even after the map proved him wrong / the guide persisted / that the trail crossed the northern ridge.','persist 可表示反复或坚定地声称某事为真。','证据相反，他仍坚持原说法。')],M('The smoke smell persisted after the fire was out, but the report said it vanished immediately and left no trace.','The smoke smell persisted after the fire was out, remaining in the hallway for several hours.','persist 表示继续存在；立即消失与持续数小时相反。','meaning'),[q('What did Mara keep requesting?','a public audit','a company car','a new trail map','她坚持要求公开审计。',1,'context'),q('What persisted after the fire was extinguished?','a faint smell of smoke','the flames themselves','a magnetic field in the archive','火熄灭后仍有烟味。',2,'context'),q('What did the guide do after seeing the map?','continued to claim the trail crossed the ridge','immediately admitted the map was correct','asked for permission to enter the museum','他仍坚称小路穿过山脊。',3,'context'),q('Which sense of persist appears in “the problem persisted”?','it continued to exist','someone demanded it repeatedly','someone insisted it was true','“问题持续存在”对应第二义。',2,'meaning')]);
P('persistence','Persistence came through French from Latin persistentia, from persistere; it is steady determination or the continuing existence of an effect.',[C('persistence.s1','坚持不懈','The researcher’s persistence paid off when a final test confirmed the result she had pursued for years.','研究者多年坚持追查，最终一次测试证实了结果，努力终于有了回报。','The researcher’s persistence paid off / when a final test confirmed / the result she had pursued for years.','persistence 指遇到困难仍持续努力的决心。','研究者多年没有放弃。'),C('persistence.s2','持续；存留','The persistence of the stain after several washes suggested that the dye had bonded with the fabric.','污渍洗了几次仍未消失，说明染料可能已与布料结合。','The persistence of the stain after several washes / suggested / that the dye had bonded with the fabric.','persistence 也可指某种现象在原因消失后继续存在。','污渍在多次清洗后仍然留下。')],M('The stain’s persistence meant it disappeared after the first wash and never returned.','The stain’s persistence meant it remained after several washes.','persistence 是持续存留，不是很快消失。','meaning'),[q('What did the final test confirm?','the result the researcher had pursued for years','that she had given up before testing','that the stain had vanished','多年坚持后，研究者终于得到结果证实。',1,'context'),q('What did the stain’s persistence suggest?','the dye had bonded with the fabric','the fabric had never been stained','the washing machine had stopped working','洗后污渍仍在，说明染料可能与布料结合。',2,'context'),q('Which meaning appears in “her persistence impressed the team”?','determination to continue despite difficulty','the lingering presence of a smell','the act of changing an order','这里 persistence 指坚持不懈的品质。',1,'meaning'),q('Which Latin verb is behind persistence?','persistere','persequi','permeare','persistence 与 persistere“坚定地持续”相关。',1,'word-formation')]);
P('persistent','Persistent comes from Latin persistentem, the present participle of persistere; it means lasting or continuing despite resistance.',C('persistent.s1','持续的；坚持不懈的','A persistent cough kept waking Daniel at night, so he made an appointment with his doctor.','持续不断的咳嗽让丹尼尔夜里总是醒来，于是他预约了医生。','A persistent cough / kept waking Daniel at night / so he made an appointment with his doctor.','persistent 可描述长时间不消退的症状，也可形容不放弃的人。','咳嗽反复持续到夜间。'),M('Daniel had a persistent cough that stopped after one brief cough and never returned.','Daniel had a persistent cough that continued to wake him on several nights.','持续的症状会反复或长久存在，不是只出现一次。','meaning'),[q('What kept waking Daniel?','a cough that continued at night','a one-time alarm that never rang again','a committee’s request for an audit','他的持续咳嗽让他夜里醒来。'),q('What does persistent mean?','continuing for a long time or despite difficulty','happening once and disappearing','permitted by a written rule','persistent 描述持续存在或坚持不懈。',1,'meaning'),q('Which person is persistent?','an applicant who revises and resubmits after several refusals','an applicant who quits before submitting anything','an employee who never returns to work','多次修改后重交申请体现坚持不懈。',1,'context'),q('Which form is the source of persistent?','the Latin present participle persistentem','the French noun permissibilité','the English plural persons','persistent 源自拉丁语 persistere 的现在分词形式。',1,'word-formation')]);
P('persistently','Persistently is the adverb from persistent; it means repeatedly or continuously, without stopping despite difficulty.',C('persistently.s1','持续不断地','The small leak persistently dripped from the ceiling until the caretaker found the cracked pipe.','小漏水持续不断地从天花板滴下，直到管理员找到裂开的管道。','The small leak persistently dripped from the ceiling / until the caretaker / found the cracked pipe.','persistently 修饰动作，强调反复持续且不停止。','滴水一直持续到管道被找到。'),M('The faucet persistently dripped, but the record said it produced one drop once and then remained completely dry.','The faucet persistently dripped, producing drops again and again until it was repaired.','persistently 表示持续反复，不是只滴一次。','context'),[q('What did the caretaker eventually find?','a cracked pipe','a company car','a trail map','管理员最终找到裂开的管道。'),q('What does persistently mean?','repeatedly or continuously without stopping','once, briefly, and never again','only when permission is granted','persistently 表示持续不断地。',1,'meaning'),q('Which action was done persistently?','the pump kept failing every few minutes despite repairs','the pump worked once and never failed','the pump was removed before anyone used it','水泵即使维修仍反复故障，体现持续反复。',1,'context'),q('What suffix forms persistently from persistent?','-ly','-ity','-ment','-ly 将形容词构成副词 persistently。',1,'word-formation')]);
P('person','Person came through French from Latin persona, first “actor’s mask or role,” later an individual human being; it can also mark grammatical person.',[C('person.s1','人；个人','Every person at the shelter received a blanket and a hot meal before nightfall.','夜幕降临前，收容所里的每个人都领到了一条毯子和一份热饭。','Every person at the shelter / received a blanket / and a hot meal before nightfall.','person 作普通名词指一个具体的人。','every 修饰单数个体。'),C('person.s2','（法律、告示中的）人','The notice states that no person may enter the laboratory without an escort.','告示写明，任何人未经陪同不得进入实验室。','The notice states / that no person may enter the laboratory / without an escort.','正式或法律语境可用 person，复数形式 persons。','规定以正式方式适用于任何个人。'),C('person.s3','人称','The grammar lesson compared first person “I” with second person “you” and third person “she.”','语法课比较了第一人称“I”、第二人称“you”和第三人称“she”。','The grammar lesson compared first person “I” / with second person “you” / and third person “she.”','语法中的 person 指说话者、听话者或所谈论对象的人称类别。','例子按第一、第二、第三人称排列。')],M('The notice stated that no person could enter alone, yet claimed that every individual could enter without an escort.','The notice stated that no person could enter the laboratory without an escort.','规定禁止无陪同进入，不能同时允许所有人独自进入。','meaning'),[q('Who received a blanket at the shelter?','every person staying there','only the caretaker','the cracked pipe','收容所里的每个人都领到毯子。',1,'context'),q('Who may enter the laboratory under the notice?','no person without an escort','every person alone','only a visitor with a company car','告示禁止任何人未经陪同进入。',2,'context'),q('Which pronoun is first person?','I','you','she','I 是第一人称代词。',3,'meaning'),q('What did persona first refer to in Latin?','an actor’s mask or role','a written job benefit','a pear drink','persona 最初可指演员的面具或角色。',1,'word-formation')]);
P('personal','Personal comes from Latin personalis, “of a person,” from persona; it means belonging to or concerning a particular individual.',C('personal.s1','个人的；私人的','Please keep your personal contact details off the public notice board.','请不要把个人联系方式贴在公共告示板上。','Please keep your personal contact details / off the public notice board.','personal 表示属于某个人或与其私人事务有关。','联系方式属于个人信息。'),M('The notice displayed personal contact details, but described them as unrelated to any individual.','The notice displayed personal contact details that identified a particular individual.','personal details 与具体个人有关，不可能同时与任何人无关。','meaning'),[q('What should stay off the public board?','personal contact details','the public opening hours','a general evacuation map','个人联系方式不应公开张贴。'),q('What does personal mean?','belonging to or concerning a particular person','shared equally by every town','relating only to a mathematical curve','personal 指与某个人有关的。',1,'meaning'),q('Which is personal information?','a person’s home phone number','the public address of a city hall','the general rules for a park','住家电话号码属于个人信息。',1,'context'),q('Which Latin word is behind personal?','persona','persequi','pernicies','personal 来自 persona“人、角色”。',1,'word-formation')]);
P('personalise','Personalise is the chiefly British spelling of personalize; it means tailor something to one individual or, in another sense, make a general issue personal.',[C('personalise.s1','个性化','The website lets users personalise the dashboard by choosing which reports appear first.','网站允许用户选择报告的显示顺序，从而个性化自己的仪表板。','The website lets users personalise the dashboard / by choosing which reports / appear first.','personalise 可指根据个人偏好调整产品、信息或空间。','用户按偏好选择面板内容。'),C('personalise.s2','针对个人','The moderator asked the candidates not to personalise the debate by attacking one another’s families.','主持人要求候选人不要把辩论变成针对个人，更不要攻击彼此的家人。','The moderator asked the candidates / not to personalise the debate / by attacking one another’s families.','personalise an issue/debate 可表示把一般问题转成针对某个人的人身攻击。','主持人要求讨论政策而非攻击家人。')],M('The candidate personalised the debate by keeping every criticism focused on the public policy and avoiding any personal attacks.','The candidate personalised the debate by directing policy criticism at an opponent’s character and family.','personalise 在此义中表示把议题针对个人；专注公共政策并避免人身攻击与之相反。','meaning'),[q('How can users personalise the dashboard?','choose which reports appear first','remove every report for every user','change the legal meaning of a permit','用户可按偏好选择报告顺序。',1,'context'),q('What did the moderator ask candidates to avoid?','turning policy debate into attacks on families','discussing any public policy','choosing reports for a dashboard','主持人要求不要攻击对方家人。',2,'context'),q('Which spelling is chiefly British?','personalise','personalizee','personelise','personalise 是主要用于英式英语的 -ise 拼法。',1,'spelling'),q('What does “personalise the debate” mean here?','direct the discussion against an individual','customize the order of reports','make the topic easier to understand','此处指把议题转成针对个人的攻击。',2,'meaning')]);
P('personality','Personality came through French and Latin personalitas, from personalis; it describes someone’s characteristic way of behaving.',C('personality.s1','性格；个性','Her calm personality helped the frightened visitors feel welcome during the evacuation drill.','她沉着的性格让受惊的访客在疏散演习中感到安心。','Her calm personality helped the frightened visitors / feel welcome / during the evacuation drill.','personality 指一个人较稳定的性格特征和行为方式。','沉着的性格影响她安抚访客的方式。'),M('Her personality was described as calm, although she panicked at every small noise and treated visitors harshly.','Her calm personality helped her reassure visitors during the drill.','若总因小动静惊慌并苛待访客，就不能说表现沉着。','meaning'),[q('What effect did her personality have on visitors?','her calm manner helped them feel welcome','she frightened them by shouting','she made them wait outside overnight','她沉着的性格让访客安心。'),q('What does personality mean?','the characteristic way a person behaves','an official document granting access','a person’s private phone number only','personality 指一个人的性格和行为方式。',1,'meaning'),q('Which trait is part of a friendly personality?','showing patience with a nervous guest','ignoring everyone who asks for help','changing a rule to punish one rival','耐心对待紧张访客体现友善性格。',1,'context'),q('What is the historical base of personality?','personalitas, related to personal','perquisitum, a job benefit','permeabilis, able to pass through','personality 与拉丁语 personalitas 有关。',1,'word-formation')]);
P('personalize','Personalize is the American -ize spelling of personalise; it means customize something for one user or make an issue about an individual.',[C('personalize.s1','个性化；标上个人记号','The library lets each borrower personalize a reading list by adding favorite subjects and authors.','图书馆允许每位借阅者添加喜欢的主题和作者，打造个性化阅读清单。','The library lets each borrower personalize a reading list / by adding favorite subjects / and authors.','personalize 可指按个人喜好定制物品或服务，也可指加上个人标记。','清单按借阅者偏好调整。'),C('personalize.s2','使针对个人','The spokesperson warned the panel not to personalize criticism of the proposal by insulting its author.','发言人提醒小组不要通过侮辱提案作者，把对提案的批评变成针对个人。','The spokesperson warned the panel / not to personalize criticism of the proposal / by insulting its author.','personalize 可表示把一般问题或争论变成针对个人。','批评方案应避免人身攻击作者。')],M('The panel personalized its criticism by discussing only the proposal’s evidence and never mentioning its author.','The panel personalized its criticism by attacking the author instead of evaluating the proposal’s evidence.','只评估证据并未针对个人；攻击作者才是把批评人格化。','meaning'),[q('How can a borrower personalize a reading list?','add preferred subjects and authors','erase every title for all borrowers','change the library’s legal name','借阅者可按喜好添加主题和作者。',1,'context'),q('What did the spokesperson warn the panel not to do?','turn criticism of a proposal into an insult against its author','check the evidence in the proposal','ask the author to clarify a data source','发言人要求不要把方案批评变成人身攻击。',2,'context'),q('Which spelling is standard in American English?','personalize','personalise','personalisee','美式英语通常拼作 personalize。',1,'spelling'),q('What does personalize mean in “personalize a notebook”?','customize it for one person','punish its owner for an idea','turn it into a legal document','这里 personalize 指为个人定制笔记本。',1,'meaning')]);
P('personally','Personally is formed from personal and -ly; it means in person or from one’s own point of view.',C('personally.s1','亲自；就本人而言','I personally checked every application before sending the final list to the review board.','我亲自核查了每份申请，然后把最终名单送交审查委员会。','I personally checked every application / before sending the final list / to the review board.','personally 可强调亲自做某事，也可引出个人观点。','说话者强调由本人检查。'),M('I personally checked every application, although I delegated the review and never opened any file myself.','I personally checked every application myself before sending the list.','personally checked 强调亲自检查，完全未打开文件与此相反。','meaning'),[q('Who checked the applications?','the speaker personally checked them','the review board checked them without the speaker','a company car checked them automatically','说话者强调自己亲自核查。'),q('What can personally mean?','in person or from one’s own point of view','belonging to an entire department','at a right angle to a wall','personally 可表示“亲自”或“就本人而言”。',1,'meaning'),q('Which sentence uses personally to state an opinion?','Personally, I prefer the quieter route.','The personnel office mailed a permit.','A persistent leak dripped overnight.','句首 Personally 引出说话者的个人看法。',1,'context'),q('Which adjective is the base of personally?','personal','perplexing','permissive','personally 由 personal 加 -ly 构成。',1,'word-formation')]);
P('personify','Personify combines person with -ify, “make into”; it means give human qualities to something or be a clear example of a quality.',[C('personify.s1','使人格化；体现','The poem personifies winter as a tired traveler knocking at each village door.','诗歌把冬天拟人化，写成一个敲响每个村庄门扉的疲倦旅人。','The poem personifies winter / as a tired traveler / knocking at each village door.','personify 可赋予抽象事物人类特征，也可指某人典型体现一种品质。','冬天被写成会疲倦、敲门的旅人。')],M('The poem personified winter by describing it as a season with no human actions or qualities at all.','The poem personified winter by giving the season human actions and qualities.','拟人写法正是赋予非人事物人的特征；题干说完全没有这些特征。','meaning'),[q('How did the poem personify winter?','as a tired traveler knocking on doors','as a temperature reading on a thermometer','as a list of monthly dates','冬天被描绘成疲倦旅人。'),q('What does personify mean?','give a nonhuman thing human qualities','remove every personal detail','make something legally permissible','personify 指赋予事物人的特征。',1,'meaning'),q('Which sentence personifies a river?','The river hurried toward the sea and whispered over the stones.','The river is 30 kilometers long.','The river appears on a map in blue.','河流“匆忙”“低语”具有人的动作，属于拟人。',1,'context'),q('What does -ify do in personify?','forms a verb meaning make or render','forms a plural noun','forms an adverb of manner','-ify 常构成表示“使成为”的动词。',1,'word-formation')]);
P('personnel','Personnel came from French personnel, “staff,” from personne; it means an organization’s employees or the department that manages them.',[C('personnel.s1','全体人员；职员','Emergency personnel arrived within minutes and guided residents away from the flooded road.','应急人员几分钟内便赶到现场，引导居民离开被淹道路。','Emergency personnel arrived within minutes / and guided residents / away from the flooded road.','personnel 作集合名词指某组织或单位的全体工作人员。','多名工作人员共同赶到并疏散居民。'),C('personnel.s2','人事部门','Please send the completed benefits form to personnel before the end of the week.','请在本周结束前把填妥的福利表送到人事部门。','Please send the completed benefits form / to personnel / before the end of the week.','personnel 也可指负责招聘、员工事务和福利的人事部门。','福利表应送交负责员工事务的部门。')],M('The company’s personnel arrived to guide residents, but the report said no employees or staff were present.','The company’s personnel arrived to guide residents, including trained emergency staff.','personnel 指职员或工作人员，不能同时说没有任何员工到场。','meaning'),[q('Who guided residents from the flooded road?','emergency personnel','the missing bridge plans','a pear orchard','应急工作人员引导居民撤离。',1,'context'),q('Where should the benefits form be sent?','to the personnel department','to the river bank','to the public notice board','表格要交给人事部门。',2,'context'),q('Which statement uses personnel as a collective noun?','The hospital hired additional personnel for the night shift.','The hospital hired one personels for the night shift.','Personnel are a type of legal permit.','personnel 可集合指医院新增工作人员。',1,'grammar'),q('What does personnel mean in “personnel office”?','the department that handles staff matters','a person’s private contact details','an individual employee’s personality','personnel office 是处理员工事务的人事部门。',2,'meaning')]);
P('persons','Persons is the formal or legal plural of person, used especially when referring to individuals separately or precisely.',C('persons.s1','人们（正式复数）','The notice states that all persons entering the archive must sign the visitor register.','告示规定，所有进入档案馆的人都必须在访客登记簿上签名。','The notice states / that all persons entering the archive / must sign the visitor register.','persons 是 person 的正式复数，常见于法律、规章或正式告示。','正式告示逐一指进入者。'),M('The notice required all persons to sign the register, but it also said that no individuals entering the archive needed to sign.','The notice required all persons entering the archive to sign the register.','persons 指进入的个人；不能同时要求全体登记又说无人需要登记。','meaning'),[q('Who must sign the archive register?','all persons entering the archive','only the archivist’s family','nobody entering the building','所有进入档案馆的人都要登记。'),q('Where is persons especially common?','in formal or legal language','only in casual speech among close friends','only in poetry about winter','persons 常用于正式或法律语境。',1,'context'),q('Which sentence uses persons naturally?','No persons other than staff may enter this room.','Three personses entered the room.','The persons of the novel was mysterious.','正式告示可用 persons 指获准进入的个人。',1,'context'),q('What is persons?','the formal plural of person','the adjective form of personality','the past tense of personify','persons 是 person 的正式复数。',1,'grammar')]);
P('perspective','Perspective entered English through Old French from Medieval Latin perspectiva ars, the science of optics; its later senses include a mental outlook and a drawing method that represents depth.',[C('perspective.s1','观点；看法','After hearing the nurses’ accounts, the committee gained a new perspective on the delays in emergency care.','听取护士们的讲述后，委员会对急诊延误有了新的看法。','After hearing the nurses’ accounts / the committee gained / a new perspective on the delays.','perspective.s1 指看待或理解某事的方式。','委员会因听取不同经历而改变看法。'),C('perspective.s2','正确判断相对重要性；全局观','The editor kept the minor typo in perspective and focused first on the false medical claim.','编辑没有把小拼写错误看得过重，而是先处理错误的医学说法。','The editor kept the minor typo in perspective / and focused first / on the false medical claim.','perspective.s2 强调判断事物重要程度及彼此关系时保持合宜比例。','先处理更严重的问题，说明编辑对轻重有合理判断。'),C('perspective.s3','透视画法','The art student used perspective to make the railway tracks appear to meet in the distance.','美术学生用透视法让铁轨看起来在远处交会。','The art student used perspective / to make the railway tracks appear / to meet in the distance.','perspective.s3 是在平面上表现远近和深度的绘画方法。','平面画中以汇聚线条表现距离。')],M('The editor put the typo in perspective by treating it as more urgent than the false medical claim and ignoring the larger risk.','The editor kept the typo in perspective by fixing the false medical claim before the minor error.','这里把轻微拼写问题当成比错误医学信息更重要，正好违背按相对重要性判断。','meaning'),[q('What changed the committee’s perspective on the delays?','hearing the nurses’ accounts','seeing a drawing of railway tracks','counting letters in the typo','护士的经历让委员会获得不同看法。',1,'context'),q('Which action shows perspective as sound judgment?','fixing the dangerous false claim before a small typo','spending all day on a harmless comma while ignoring a safety defect','drawing parallel tracks that meet at the horizon','先处理危险错误体现对轻重缓急的判断。',2,'meaning'),q('What does perspective do in the student’s picture?','makes the tracks seem to meet far away','records how each nurse felt','proves which medical claim is true','透视法让铁轨显得在远处交会。',3,'context'),q('Which meaning is tested by “a fresh perspective on the dispute”?','a way of understanding the dispute','a method for showing depth in a painting','a calculation of the dispute’s exact length','这里 perspective 指理解争议的角度。',1,'meaning')]);
P('perspicacious','Perspicacious was formed from Latin perspicax, “sharp-sighted,” from perspicere, “look through closely”; it describes keen judgment that notices what others miss.',C('perspicacious.s1','有洞察力的；敏锐的','A perspicacious reviewer noticed that the chart used two different scales, exposing the misleading comparison.','一位有洞察力的审稿人发现图表使用了两种不同刻度，揭穿了误导性比较。','A perspicacious reviewer noticed / that the chart used two different scales / exposing the misleading comparison.','perspicacious 形容能迅速看出不明显问题并作出准确判断的人。','审稿人发现图表中隐藏的刻度差异。'),M('The perspicacious reviewer missed the two different scales and accepted the misleading comparison without noticing a problem.','The perspicacious reviewer spotted the two different scales and questioned the comparison.','漏掉关键差异并未察觉问题，不能体现敏锐洞察。','meaning'),[q('What did the reviewer detect?','the chart’s two different scales','a missing train ticket','the poem’s winter metaphor','审稿人发现了图表的刻度问题。'),q('Who is perspicacious?','a person who quickly notices subtle facts and judges well','a person who refuses to examine any evidence','a device that measures room temperature','perspicacious 描述洞察敏锐、判断准确的人。',1,'meaning'),q('Which action is perspicacious?','spotting that a supposedly identical test used different controls','copying the headline without reading the report','ignoring a mismatch in the data','发现对照条件不同体现敏锐判断。',1,'context'),q('Which word is closest in meaning to perspicacious?','shrewd','careless','perspiring','shrewd 表示精明敏锐，与 perspicacious 接近。',1,'word-choice')]);
P('perspicacity','Perspicacity came through French from Late Latin perspicacitas, “sharp-sightedness or discernment,” based on perspicax; it names keen perception and judgment.',C('perspicacity.s1','洞察力；敏锐的判断力','Her perspicacity led her to ask why the “free” trial required a payment card and automatic renewal.','她的敏锐洞察使她追问，为什么“免费”试用仍要求提供银行卡并自动续订。','Her perspicacity led her to ask / why the “free” trial required / a payment card and automatic renewal.','perspicacity 是迅速发现隐含问题并作出判断的能力。','她察觉免费试用条款中隐藏的自动扣费条件。'),M('His perspicacity prevented him from noticing the automatic renewal clause and signing up without reading it.','His perspicacity helped him notice the automatic renewal clause before signing up.','忽略关键条款说明缺乏敏锐判断，而不是拥有洞察力。','meaning'),[q('What did her perspicacity make her question?','the card requirement and automatic renewal','the trial’s color scheme','the spelling of a distant city','她发现试用服务背后的扣费条件。'),q('What is perspicacity?','keen perception and sound judgment','a form used to renew a passport','the act of sweating heavily','perspicacity 指敏锐的洞察和判断力。',1,'meaning'),q('Which choice shows perspicacity?','noticing that a “no-fee” offer adds an undisclosed service charge','accepting every condition without looking','asking how to spell the word “trial”','识破免费宣传中的隐藏费用体现洞察力。',1,'context'),q('Which adjective shares the same word family?','perspicacious','perspired','perishable','perspicacious 是表示“有洞察力的”的同源形容词。',1,'word-formation')]);
P('perspicuous','Perspicuous comes from Latin perspicuus, “transparent or clear,” from perspicere, “look through”; it describes writing or speech that is lucid and well arranged.',C('perspicuous.s1','明白易懂的；清晰有条理的','The perspicuous safety guide labels each step and explains every warning before the user handles the chemical.','这份清晰易懂的安全指南为每一步标注，并在读者接触化学品前解释所有警告。','The perspicuous safety guide / labels each step / and explains every warning.','perspicuous 主要形容表达或文字清楚、条理分明。','指南将操作步骤和警告解释得清楚明白。'),M('The perspicuous guide hid its instructions in vague jargon and left readers unable to understand the procedure.','The perspicuous guide stated the procedure clearly and explained its technical terms.','含混术语使指南难以理解；perspicuous 指表达清楚。','meaning'),[q('What makes the safety guide perspicuous?','it labels steps and explains warnings clearly','it hides the directions in unexplained jargon','it lists chemical prices without instructions','指南的步骤和警告解释清楚。'),q('Which writing is perspicuous?','a well-organized notice that explains each requirement plainly','a paragraph filled with undefined abbreviations','a page whose instructions contradict one another','条理清楚、解释明白的通知是 perspicuous。',1,'meaning'),q('Perspicuous most nearly means what here?','lucid and easy to understand','expensive to produce','written from a personal viewpoint','perspicuous 指表达清晰易懂。',1,'meaning'),q('Which noun describes the quality of being perspicuous?','perspicuity','persecution','perspiration','perspicuity 表示清晰、明白的性质。',1,'word-formation')]);
P('perspiration','Perspiration came through French from Latin perspirare, “breathe or blow through,” formed from per “through” and spirare “breathe”; it later came to mean sweat.',C('perspiration.s1','汗液；出汗','Perspiration ran down the runner’s face after the final hill, so she stopped to drink water.','跑者翻过最后一段山坡后汗水从脸上流下，于是停下来喝水。','Perspiration ran down the runner’s face / after the final hill / so she stopped to drink water.','perspiration 指身体排出的汗液，也可指出汗这一过程。','运动后脸上流汗。'),M('After the hot race, no perspiration appeared on the runner’s skin, yet sweat ran down her face.','After the hot race, perspiration covered the runner’s skin and ran down her face.','汗水就是 perspiration；说没有汗液却有汗流下相互矛盾。','meaning'),[q('Why did the runner stop after the hill?','perspiration was running down her face and she needed water','she needed to check the chart’s drawing scale','she had to review a legal clause','跑者出汗后停下来喝水。'),q('What does perspiration mean?','sweat or the process of sweating','a clear method of drawing depth','a reasoned argument that changes a decision','perspiration 指汗液或出汗。',1,'meaning'),q('Which situation involves perspiration?','sweat forming while someone exercises in heat','a document becoming clearer after editing','a legal claim belonging to a property','炎热运动时产生汗液。',1,'context'),q('Which Latin verb is part of perspiration’s history?','spirare, “to breathe”','specere, “to look at”','tenere, “to hold”','词源中的 spirare 表示“呼吸”。',1,'word-formation')]);
P('perspire','Perspire was built from Latin perspirare, “breathe through,” and was reinforced by the related noun perspiration; in present use it means produce sweat.',C('perspire.s1','出汗','Even in the air-conditioned clinic, the anxious patient began to perspire while waiting for the test result.','即使诊所在开空调，焦虑的病人等待检查结果时还是开始出汗。','Even in the air-conditioned clinic / the anxious patient began to perspire / while waiting for the result.','perspire 是动词，表示身体排出汗液。','焦虑时开始出汗。'),M('The patient began to perspire, but no sweat or moisture came from the body at all.','The patient began to perspire as sweat appeared on the forehead.','perspire 就是出汗，不能同时说身体毫无汗液。','meaning'),[q('What caused the patient to perspire in the clinic?','anxiety while waiting for the test result','a need to draw a perspective diagram','a request to join a committee','病人焦虑等待时开始出汗。'),q('Which sentence uses perspire correctly?','The hikers perspired heavily during the hot climb.','The hikers perspired the map into a clear diagram.','The hikers perspired the report to the committee.','perspire 作不及物动词表示出汗。',1,'grammar'),q('What does perspire mean?','to produce sweat','to persuade someone by reasoning','to look through a transparent object','perspire 指身体出汗。',1,'meaning'),q('What noun names the sweat produced?','perspiration','perspicacity','perspective','perspiration 是“汗液；出汗”。',1,'word-formation')]);
P('persuade','Persuade comes from Latin persuadere, “urge or convince,” from per “thoroughly” and suadere “advise”; it means reason someone into acting or believing.',[C('persuade.s1','说服某人做某事','After comparing the repair estimates, Mina persuaded her landlord to replace the unsafe wiring.','比较维修报价后，米娜说服房东更换了不安全的电线。','After comparing the estimates / Mina persuaded her landlord / to replace the unsafe wiring.','persuade.s1 常见结构为 persuade someone to do something，表示说服某人采取行动。','房东听取报价后同意更换电线。'),C('persuade.s2','使某人相信','The repeated measurements persuaded the researchers that the apparent improvement was not a measurement error.','反复测量使研究人员相信，表面上的改善并非测量误差。','The repeated measurements persuaded the researchers / that the improvement / was not a measurement error.','persuade.s2 后接 that 从句时表示使某人相信某一判断。','多次测量让研究人员相信结果可靠。')],M('Mina persuaded her landlord replace the wiring, and the researchers persuaded that the data were reliable.','Mina persuaded her landlord to replace the wiring, and the researchers were persuaded that the data were reliable.','persuade sb to do 与 be persuaded that 是规范搭配；主动句漏掉 to 且第二句缺少受事主语。','grammar'),[q('What did Mina persuade the landlord to do?','replace the unsafe wiring','redraw a railway perspective','remove the clinic’s air conditioning','她说服房东更换不安全的电线。',1,'context'),q('What did the measurements persuade the researchers?','that the improvement was not a measurement error','to replace the building wiring','that the chart used two drawing scales','测量使研究人员相信改善并非误差。',2,'context'),q('Which structure is correct?','persuade someone to take action','persuade someone taking action','persuade someone for take action','常用结构为 persuade someone to do something。',1,'grammar'),q('Which sentence means “make someone believe a claim”?','The evidence persuaded us that the sample was contaminated.','The evidence persuaded us to label every tube.','The evidence pervaded the room with a smell.','that 从句表示说服某人相信该判断。',1,'meaning')]);
P('persuasion','Persuasion comes through French from Latin persuasionem, from persuadere, “convince”; it means the act of talking someone into agreement or the skill of doing so.',[C('persuasion.s1','说服；劝服的行为','The volunteers used calm persuasion to convince hesitant residents to receive the flood alert.','志愿者用平和的劝说使犹豫的居民愿意接收洪水警报。','The volunteers used calm persuasion / to convince hesitant residents / to receive the alert.','persuasion.s1 指通过言辞使人同意或采取行动的过程。','志愿者劝说居民接受警报。'),C('persuasion.s2','说服力；劝说能力','The negotiator’s persuasion was strongest when she listened carefully before answering objections.','谈判者先认真倾听再回应异议时，最能展现她的说服力。','The negotiator’s persuasion was strongest / when she listened carefully / before answering objections.','persuasion.s2 指说服他人的能力或技巧。','谈判者的倾听和回应展现劝说能力。')],M('The volunteers used persuasion to discourage residents from receiving the emergency alert, while the notice said they urged everyone to accept it.','The volunteers used persuasion to encourage residents to receive the emergency alert.','原句中“劝居民不要接收”与“劝大家接收”目标相反。','meaning'),[q('What did the volunteers try to persuade residents to do?','receive the flood alert','sign up for a painting class','ignore every warning','志愿者劝居民接收洪水警报。',1,'context'),q('What is persuasion in the negotiator example?','the ability to influence people through skillful discussion','the act of drawing railroad tracks in depth','the sweat produced during a heated meeting','谈判者展现的是劝说他人的能力。',2,'meaning'),q('Which phrase means the act of convincing someone?','an attempt at persuasion','a sense of perspective','a burst of perspiration','an attempt at persuasion 表示劝说行为。',1,'meaning'),q('Which verb forms the base of persuasion?','persuade','peruse','pertain','persuasion 是 persuade 的名词形式。',1,'word-formation')]);
P('persuasive','Persuasive is formed from persuade plus -ive; it describes an argument or speaker that can make people accept an idea or take action.',C('persuasive.s1','有说服力的','The persuasive presentation paired audited figures with a clear explanation of how the grant would reduce emergency-room waits.','这场有说服力的陈述将审计数据与清晰说明结合起来，解释拨款如何减少急诊等待。','The persuasive presentation paired audited figures / with a clear explanation / of the expected reduction in waits.','persuasive 形容能够促使别人接受观点或采取行动的内容或表达。','数据和具体机制共同支持拨款方案。'),M('Her persuasive case relied on invented figures and left the committee less willing to support the grant.','Her persuasive case used verified figures and a clear plan to win the committee’s support.','捏造数字削弱可信度和说服效果，不能构成有效的 persuasive 论据。','meaning'),[q('Why was the grant presentation persuasive?','it linked audited figures to a clear plan for shorter waits','it omitted every number and refused questions','it described how to draw depth on a flat page','陈述以核实数据支持明确方案，因此具有说服力。'),q('What does persuasive describe?','able to make someone accept an idea or act','already sweating heavily','belonging to a different subject','persuasive 指有能力使人接受观点或采取行动。',1,'meaning'),q('Which claim is most persuasive to a budget committee?','a verified cost estimate tied to measurable results','an unsupported promise that “everything will improve”','a drawing with no relation to the proposal','可核实的费用与可测结果能增强说服力。',1,'context'),q('Which noun is the base of persuasive?','persuade','perspective','persecute','persuasive 由 persuade 加形容词后缀构成。',1,'word-formation')]);
P('persuasively','Persuasively is the adverb formed from persuasive; it means in a way that can lead someone to believe or do something.',C('persuasively.s1','有说服力地','The engineer persuasively explained why replacing the cracked valve now would prevent a much costlier shutdown.','工程师有说服力地解释了为什么现在更换裂纹阀门可以避免代价高得多的停产。','The engineer persuasively explained / why replacing the cracked valve now / would prevent a costly shutdown.','persuasively 修饰 explained，说明解释足以使听众接受该方案。','解释把即时维修与避免停产的关系说清。'),M('The engineer spoke persuasively, but deliberately hid the repair costs and gave no reason for replacing the valve.','The engineer spoke persuasively by explaining the repair costs and the shutdown risk.','隐瞒成本又不说明理由，无法支撑“有说服力地”这一评价。','meaning'),[q('How did the engineer speak?','in a way that made the repair plan convincing','in a way that caused everyone to sweat','in a way that showed railway depth','persuasively 描述工程师有说服力的解释方式。'),q('Which word does persuasively modify in this sentence?','explained','valve','shutdown','副词 persuasively 修饰动词 explained。',1,'grammar'),q('Why was the proposed repair convincing?','it could prevent a much more expensive shutdown','it would make the valve a new perspective','it required hiding all costs','更换阀门能避免更贵的停产，形成有力理由。',1,'context'),q('What is the adjective form related to persuasively?','persuasive','perspiring','perspicuous','persuasively 由 persuasive 加 -ly 构成。',1,'word-formation')]);
P('pertain','Pertain entered English from Old French partenir and Latin pertinere, “reach, relate, or belong”; it means be connected with a subject or form part of it.',C('pertain.s1','与……有关；属于','The appendix contains only records that pertain to the 2024 trial, not earlier studies.','附录只收录与 2024 年试验有关的记录，不包括更早的研究。','The appendix contains only records / that pertain to the 2024 trial / not earlier studies.','pertain to 表示与某主题有关，或属于该主题范围。','附录按主题筛选相关记录。'),M('The appendix includes records that pertain to the 2024 trial, although none of them are related to that trial.','The appendix includes records that pertain to the 2024 trial and are directly related to it.','pertain to 意为相关；又说这些记录均无关，前后矛盾。','meaning'),[q('Which records belong in the appendix?','records related to the 2024 trial','records about an unrelated city’s weather','every document from every year','附录收录与试验相关的记录。'),q('What does pertain to mean?','be related to or form part of','sweat through the skin','make a person believe by arguing','pertain to 指与……有关或属于……。',1,'meaning'),q('Which sentence uses the usual preposition?','These rules pertain to all visitors.','These rules pertain at all visitors.','These rules pertain by all visitors.','pertain 通常与 to 连用。',1,'grammar'),q('A regulation about lab access would pertain to what?','who may enter the laboratory','how a painter shows distance','how much a runner sweats','实验室出入规定与谁可以进入实验室有关。',1,'context')]);
P('perth','Perth is the proper name of Western Australia’s capital; Australia’s city was named after the Scottish city of Perth when the Swan River Colony was established in 1829.',C('perth.s1','珀斯（西澳大利亚州首府）','The research team flew to Perth before driving north to survey coral reefs along the coast.','研究团队先飞往珀斯，随后驾车北上调查海岸珊瑚礁。','The research team flew to Perth / before driving north / to survey coastal coral reefs.','Perth 在本词条中是西澳大利亚州首府的专名。','目的地是澳大利亚城市珀斯。'),M('The itinerary says the team landed in Perth, the capital of Western Australia, but identifies the city as a town in Scotland.','The itinerary says the team landed in Perth, the capital of Western Australia, before continuing along the coast.','澳大利亚首府 Perth 与苏格兰同名城市是两个地方；行程不能把前者说成苏格兰城镇。','meaning'),[q('Where did the research team fly first?','Perth in Western Australia','a Scottish town on the same itinerary','a laboratory inside the coral reef','团队先飞往西澳大利亚州首府珀斯。'),q('Which country is Perth the capital city of?','Australia','Canada','New Zealand','Perth 是澳大利亚西澳大利亚州首府。',1,'meaning'),q('What was the Australian city named after?','the Scottish city of Perth','a Latin word for “persuade”','the Swan River coral reef','澳大利亚的珀斯以苏格兰同名城市命名。',1,'word-formation'),q('Which sentence uses Perth as a place name?','Perth lies on the Swan River in Western Australia.','The runner perspired across the park.','The article’s argument was persuasive.','此句中的 Perth 是具体城市专名。',1,'context')]);
P('pertinent','Pertinent comes from Latin pertinere, “relate to or belong”; it describes information directly relevant to the matter being discussed.',C('pertinent.s1','相关的；切题的','The judge allowed only pertinent questions about the witness’s account of the collision.','法官只允许提出与证人所述碰撞经过直接相关的问题。','The judge allowed only pertinent questions / about the witness’s account / of the collision.','pertinent 表示与当前讨论的问题直接相关。','问题聚焦于碰撞经过。'),M('The judge called the witness’s favorite dessert pertinent to the collision even though it had no connection to the event.','The judge called the witness’s account of the collision pertinent to the case.','与案件毫无关系的甜点偏好并非切题证据。','meaning'),[q('What kind of questions did the judge allow?','questions directly related to the collision','questions about unrelated desserts','questions about the witness’s vacation plans','法官只允许与碰撞案有关的问题。'),q('What does pertinent mean?','directly relevant to the matter','able to make a person sweat','drawn to show distance on a flat surface','pertinent 指直接相关、切题。',1,'meaning'),q('Which detail is pertinent to a broken-pipe investigation?','when the leak began and where water appeared','the inspector’s favorite film','the color of a distant train','漏水时间和位置与管道调查直接相关。',1,'context'),q('Which preposition commonly follows pertinent?','to','at','by','常见结构是 pertinent to。',1,'grammar')]);
P('perturb','Perturb came through Old French from Latin perturbare, “disturb or throw into disorder,” built from per and turbare; it means unsettle someone or disrupt a system.',C('perturb.s1','使不安；扰乱','The unexplained alarm perturbed the night-shift staff, who could not find any sign of smoke.','莫名响起的警报让夜班员工不安，因为他们找不到任何烟雾迹象。','The unexplained alarm perturbed the staff / who could not find / any sign of smoke.','perturb 可使人焦虑不安，也可指扰乱某个系统或秩序。','警报与无烟迹象相互矛盾，令员工担忧。'),M('The unexplained alarm perturbed the staff by making them completely calm and certain that a fire had started.','The unexplained alarm perturbed the staff by making them anxious about a possible fire.','令员工完全平静与焦虑不安意思相反；且没有证据不能断定发生火灾。','meaning'),[q('Why were the night-shift staff perturbed?','the alarm had no obvious cause and they saw no smoke','they had received a clear, routine all-safe message','they were asked to review a drawing','无明显原因的警报且没有烟雾，使员工不安。'),q('What can perturb someone?','an unexpected event that unsettles them','a clear explanation that resolves every concern','a list of unrelated vocabulary words','perturb 指使人不安或扰乱。',1,'meaning'),q('Which sentence uses perturb figuratively for a system?','The power surge perturbed the sensor network and scrambled its readings.','The sensor network persuaded the committee to leave.','The sensor network perspired in the heat.','电涌扰乱了网络读数，使用 perturb 的系统义。',1,'context'),q('What does the Latin element turbare contribute?','the idea of disturbing or throwing into disorder','the idea of seeing through a lens','the idea of holding something tightly','perturbare 中 turbare 表示扰乱。',1,'word-formation')]);
P('peruse','Peruse appeared in late Middle English from per- “thoroughly” plus use; it means read or examine a text carefully rather than glance at it.',C('peruse.s1','仔细阅读；认真查看','Before signing, the tenants perused every page of the lease and marked the clauses about repairs.','签字前，租户们仔细阅读了租约的每一页，并标出维修条款。','Before signing / the tenants perused every page / and marked the repair clauses.','peruse 表示认真通读或检视文字、文件。','租户逐页阅读并标注条款。'),M('The tenants perused the lease by glancing at its cover and signing without reading any of the clauses.','The tenants perused the lease by reading its clauses carefully before signing.','只看封面而未读内容不属于仔细阅读。','meaning'),[q('What did the tenants do before signing?','read the lease carefully and mark repair clauses','draw the lease as a perspective sketch','persuade the landlord to ignore every clause','租户认真读租约并标记维修条款。'),q('What does peruse mean in the lease example?','examine a text carefully','skim only its cover','sweat while holding it','peruse 指认真阅读或查看。',1,'meaning'),q('Which action is perusing a report?','checking each section and its supporting figures closely','seeing the title and closing the file','copying one sentence without reading the rest','仔细检查各部分和数据属于 peruse。',1,'context'),q('Which element contributes the idea “thoroughly” in peruse?','per-','-ness','-ly','peruse 中 per- 有“彻底地”这一构词成分。',1,'word-formation')]);
P('pervade','Pervade comes from Latin pervadere, “go through or spread through,” from per “through” and vadere “go”; it means be present throughout every part.',C('pervade.s1','弥漫；遍布','A smell of toasted cumin pervaded the apartment after the neighbors opened their kitchen door.','邻居打开厨房门后，烤孜然的香气弥漫了整套公寓。','A smell of toasted cumin pervaded the apartment / after the neighbors opened / their kitchen door.','pervade 表示某种气味、情绪或特征遍及整体各处。','香气从厨房扩散到公寓各处。'),M('The odor pervaded the apartment, but it remained sealed inside one unopened jar and reached no other room.','The odor pervaded the apartment, spreading from the kitchen into the other rooms.','若气味只留在密封罐中、未到达其他房间，就没有弥漫整个公寓。','meaning'),[q('What pervaded the apartment?','the smell of toasted cumin','a written perspective on the lease','a warning about a sensor alarm','烤孜然的香气弥漫了公寓。'),q('What does pervade mean?','spread through and be present throughout','persuade someone to sign a document','make a drawing look three-dimensional','pervade 指遍布整体各处。',1,'meaning'),q('Which condition can pervade a workplace?','a sense of distrust felt across the whole team','one private note kept in a locked drawer','a single chair placed in one office','整个团队普遍感受到的不信任可遍布职场。',1,'context'),q('Which parts form pervade’s Latin source?','per “through” and vadere “go”','per “person” and spirare “sweat”','specere “look” and tenere “hold”','pervadere 由“通过”和“行走”构成。',1,'word-formation')]);
P('pervasive','Pervasive was formed from pervade plus -ive; it describes something widespread and difficult to keep out or contain.',C('pervasive.s1','遍布各处的；无处不在的','The audit found a pervasive pattern of missing labels across all four laboratories, not a single isolated mistake.','审计发现四间实验室都普遍存在标签缺失，并非个别错误。','The audit found a pervasive pattern / across all four laboratories / not a single isolated mistake.','pervasive 表示现象广泛存在于许多部分或场所。','问题遍及所有实验室。'),M('The audit called the problem pervasive even though it found one isolated missing label and no other cases.','The audit called the problem pervasive because missing labels appeared in all four laboratories.','单个孤立案例不能支撑“遍布各处”的判断。','meaning'),[q('Where did the audit find the missing-label pattern?','across all four laboratories','inside one isolated drawer only','on a single street sign','问题出现在所有实验室，具有普遍性。'),q('What does pervasive mean?','widespread and present throughout','limited to one isolated case','able to convince people by arguing','pervasive 指广泛存在、遍布各处。',1,'meaning'),q('Which is a pervasive problem?','a software error affecting every department','one typo on one retired form','a single unanswered question in one meeting','影响每个部门的软件错误是普遍性问题。',1,'context'),q('Which verb is the base of pervasive?','pervade','perturb','peruse','pervasive 由 pervade 加 -ive 构成。',1,'word-formation')]);
P('perverse','Perverse came from Old French and Latin perversus, “turned aside or contrary,” the past participle of pervertere; it describes stubbornly choosing what is unreasonable or wrong.',C('perverse.s1','执拗地反常的；不合情理的','In a perverse attempt to save time, the contractor ignored the safety checklist and caused a longer shutdown.','承包商为了省时间而执拗地无视安全检查表，结果造成了更长时间的停工。','In a perverse attempt to save time / the contractor ignored the checklist / and caused a longer shutdown.','perverse 可形容故意违背常理、结果适得其反的行为。','为了省时却造成更久停工，行为明显违背常理。'),M('It was sensible rather than perverse for the contractor to follow the required safety check before restarting the machine.','It was perverse for the contractor to skip the required check in order to save time and then cause a longer shutdown.','遵守安全程序是合理行为；故意省掉它并产生相反结果才符合 perverse。','meaning'),[q('What was perverse about the contractor’s choice?','skipping a safety step to save time caused a longer shutdown','following the checklist prevented any delay','measuring the machine from a new perspective','省掉检查想省时间，却导致停工更久，做法反常。'),q('What does perverse describe here?','stubbornly unreasonable or contrary behavior','clear and well-organized writing','a city on the Swan River','perverse 指执拗地违背常理或正确做法。',1,'meaning'),q('Which action is perverse?','rejecting a working solution solely to make the task harder','choosing a safe method because it works','changing a plan after receiving relevant evidence','明知有效却只为增加困难而拒绝方案，属反常执拗。',1,'context'),q('Which Latin verb underlies perversus?','pervertere, “turn away or corrupt”','pervadere, “spread through”','persuadere, “convince”','perversus 源于 pervertere。',1,'word-formation')]);
P('perversely','Perversely is the adverb formed from perverse plus -ly; it means in a way that opposes what is reasonable or wanted.',C('perversely.s1','反常地；偏偏','The outdated rule perversely charged the smallest clinics the highest fee, despite their limited budgets.','这条过时规定偏偏向预算有限的小诊所收取最高费用。','The outdated rule perversely charged / the smallest clinics / the highest fee.','perversely 修饰 charged，说明收费方式与公平、合理的预期相反。','负担能力最弱的诊所反而被收费最多。'),M('The rule perversely treated every clinic according to its budget, giving the smallest clinics the lowest fee.','The rule perversely charged the smallest clinics the highest fee despite their limited budgets.','按预算给小诊所最低费用是合理照顾；不合情理的是反而收费最高。','meaning'),[q('How did the rule perversely treat small clinics?','it charged them the highest fee despite their limited budgets','it waived every fee for every clinic','it charged only clinics with large budgets','规则反而向预算最少的诊所收费最高。'),q('What does perversely mean in this sentence?','in a way contrary to what is reasonable or expected','in a clear and easy-to-understand way','by carefully reading every page','perversely 指反常地、与合理预期相反地。',1,'meaning'),q('Which outcome happened perversely?','the least-resourced team received the largest workload','the best-funded group received the extra equipment','the safety check prevented an accident','资源最少的团队反而承担最大工作量，结果不合理。',1,'context'),q('Which adjective forms the adverb perversely?','perverse','pertinent','persuasive','perversely 由 perverse 加 -ly 构成。',1,'word-formation')]);
P('pervert','Pervert came through Old French from Latin pervertere, “turn the wrong way”; as a verb it means distort something from a fair or proper course, and as a noun it is a stigmatizing label for a person whose sexual behavior is judged abnormal.',[C('pervert.s1','歪曲；使不正当','The official perverted the safety rule by applying it only to rival firms and exempting his own company.','这名官员只把安全规定用来约束竞争公司，却让自家公司豁免，歪曲了规定。','The official perverted the safety rule / by applying it only to rivals / and exempting his own company.','pervert.s1 作动词表示歪曲原则、程序或信息，使其偏离公正用途。','规则被选择性地用于竞争者。'),C('pervert.s2','性行为被认为反常的人（带污名的称呼）','The novel’s narrator calls the accused man a “pervert,” a stigmatizing label that reveals the narrator’s judgment rather than a neutral diagnosis.','小说叙述者把被告男子称作“pervert”；这是带污名的标签，体现叙述者的评判，并非中性诊断。','The narrator calls the accused man a “pervert” / a stigmatizing label / rather than a neutral diagnosis.','pervert 作名词是贬损性、带污名的称呼；谈论真实的人时应优先使用准确且尊重的描述。','句中通过引述小说用词说明其评价色彩。')],M('The official perverted the safety rule fairly by applying it equally to his company and every rival.','The official perverted the safety rule by exempting his company while penalizing its rivals.','平等适用规定是公平的；偏袒自家公司才是歪曲规则。','meaning'),[q('How did the official pervert the safety rule?','he exempted his own company but used the rule against rivals','he applied the rule equally to every firm','he explained the rule in clear language','官员偏袒自己公司并打击对手，歪曲了规定。',1,'context'),q('What does the verb pervert mean in the safety example?','distort a rule or process from its fair purpose','persuade someone with sound reasons','spread evenly through every room','pervert 作动词指歪曲规则或程序。',1,'meaning'),q('How is the noun pervert presented in the novel sentence?','as a stigmatizing label used by the narrator, not a neutral diagnosis','as a formal job title for a safety inspector','as a respectful term that should replace a person’s name','句子明确将其作为叙述者使用的带污名称呼。',2,'context'),q('Which Latin verb is the source of pervert?','pervertere, “turn the wrong way”','pervadere, “spread through”','perspicere, “look closely”','pervert 源自表示“向错误方向转动”的 pervertere。',1,'word-formation')]);
P('pesky','Pesky appeared in New England dialect in the late 18th century, perhaps formed from pest; the origin is not certain, and it describes something persistently irritating.',C('pesky.s1','烦人的；难缠的','A pesky pop-up kept covering the evacuation map whenever the dispatcher tried to read it.','调度员每次想看疏散地图时，恼人的弹窗都会挡住地图。','A pesky pop-up kept covering the map / whenever the dispatcher tried / to read it.','pesky 形容持续造成恼人小麻烦的事物。','弹窗反复遮挡正在使用的地图。'),M('The pop-up was pesky because it appeared once, closed itself, and never interrupted the dispatcher again.','The pop-up was pesky because it kept returning and covering the dispatcher’s map.','只出现一次且不再打扰并不能说明它持续烦人。','meaning'),[q('What made the pop-up pesky?','it repeatedly covered the map','it translated the map correctly','it stayed closed all day','弹窗反复遮住地图，造成干扰。'),q('What does pesky mean?','persistently irritating or troublesome','large enough to cover a city','certain to spread a fatal disease','pesky 指恼人、难缠的。',1,'meaning'),q('Which problem is pesky?','a loose button that keeps snagging the same pocket','a repaired latch that now works smoothly','a one-time note that gives useful directions','反复勾住衣袋的松扣是恼人的小问题。',1,'context'),q('Which word may have influenced the uncertain formation of pesky?','pest','perspective','petrify','pesky 可能是由 pest 方言构成。',1,'word-formation')]);
P('pessimism','Pessimism was borrowed from French pessimisme, modeled on optimism and based on Latin pessimus, “worst”; it means expecting bad outcomes or the view that life tends to go badly.',[C('pessimism.s1','悲观；倾向于预期最坏结果','Despite strong sales, the analyst’s pessimism led her to forecast a sharp decline after the temporary discount ended.','尽管销量强劲，分析师仍因悲观而预测临时折扣结束后销量会大幅下降。','Despite strong sales / the analyst’s pessimism led her / to forecast a sharp decline.','pessimism.s1 指习惯性把最坏结果放在前面考虑的倾向。','即使当前销售强劲仍预测大跌。'),C('pessimism.s2','悲观主义','The essay describes pessimism as the belief that suffering and disappointment dominate human life.','这篇文章把悲观主义描述为一种认为痛苦和失望主宰人生的看法。','The essay describes pessimism / as the belief / that suffering dominates human life.','pessimism.s2 指认为人生整体趋于恶劣或痛苦的哲学观点。','这里谈的是对人生整体的哲学判断。')],M('Her pessimism made her predict certain success even after the company lost its largest customer.','Her pessimism made her predict another setback after the company lost its largest customer.','预期坏结果体现悲观；把严重挫折说成必然成功与 pessimism 相反。','meaning'),[q('What did the analyst forecast despite strong sales?','a decline after the discount ended','a permanent increase in every market','a sudden change in the company’s name','分析师悲观地预测折扣结束后销量下降。',1,'context'),q('Which meaning of pessimism appears in the essay?','the view that suffering and disappointment dominate life','a temporary irritation caused by a pop-up','a written request to an authority','文章讨论把人生看作由痛苦主导的悲观主义。',2,'meaning'),q('What is pessimism?','a tendency to expect bad outcomes','a guarantee that the worst outcome will happen','a scientific method for measuring flowers','悲观是预期不利结果的倾向。',1,'meaning'),q('Which Latin word is the root of pessimism?','pessimus, “worst”','petra, “rock”','petere, “ask”','pessimism 的词源基于表示“最坏”的 pessimus。',1,'word-formation')]);
P('pessimist','Pessimist was formed from pessimism with the agent suffix -ist; it names a person who habitually expects the worst.',C('pessimist.s1','悲观主义者；总做最坏打算的人','When the bridge test passed, the pessimist still asked whether the next storm would expose a hidden weakness.','桥梁测试通过后，这位悲观者仍追问下一场风暴会不会暴露隐患。','When the bridge test passed / the pessimist still asked / whether a later storm would expose a weakness.','pessimist 指习惯预期最坏情况的人。','测试通过仍担心未来风险。'),M('The pessimist expected every plan to succeed and never considered a possible failure.','The pessimist expected a hidden weakness to appear despite the successful bridge test.','从不预想失败而总预期成功，不符合 pessimist 的含义。','meaning'),[q('What worried the pessimist after the bridge test?','a future storm might reveal a hidden weakness','a flower might grow a new petal','a petition might change its title','他仍担心未来风暴会暴露隐患。'),q('Who is a pessimist?','someone who habitually expects the worst','someone who always assumes everything will work perfectly','someone who signs a formal request','pessimist 指总做最坏打算的人。',1,'meaning'),q('Which response sounds pessimistic?','“The repair may fail again even after this successful test.”','“Every risk is gone forever.”','“The test measured the bridge accurately.”','预期修复仍可能失败，体现悲观倾向。',1,'context'),q('Which noun is the base of pessimist?','pessimism','pesticide','petrifaction','pessimist 由 pessimism 加 -ist 构成。',1,'word-formation')]);
P('pessimistic','Pessimistic is the adjective formed from pessimist and pessimism; it describes expecting bad results rather than favorable ones.',C('pessimistic.s1','悲观的；预期坏结果的','The forecast was pessimistic: it predicted that the dry reservoir would not refill before summer.','这份预测很悲观：它预计干涸的水库到夏季前都不会蓄满。','The forecast was pessimistic / it predicted / the reservoir would not refill before summer.','pessimistic 形容对结果作出不利、悲观的预期。','预测水库短期内不会恢复。'),M('The report was pessimistic because it confidently predicted that every dry reservoir would refill tomorrow.','The report was pessimistic because it predicted that the reservoir would remain low through summer.','确信水库马上蓄满是乐观预测，并非 pessimistic。','meaning'),[q('What did the pessimistic forecast predict?','the reservoir would stay low until after summer','the reservoir would refill tomorrow','the reservoir had already become a flower garden','预测认为水库夏季前不会蓄满。'),q('What does pessimistic mean?','expecting that bad things will happen','confident that the best outcome is certain','annoyed by one small interruption','pessimistic 指预计坏事会发生。',1,'meaning'),q('Which comment is pessimistic about a project?','“Even with the extra staff, we may miss the deadline.”','“The work is certain to finish early.”','“The project has three stages.”','即使增派人员仍可能延误，属于悲观预期。',1,'context'),q('Which noun is closely related to pessimistic?','pessimism','petition','petiole','pessimistic 与 pessimism 同词族。',1,'word-formation')]);
P('pest','Pest came through French peste from Latin pestis, “plague or bane,” a word of uncertain deeper origin; it can mean a damaging insect or a persistently annoying person.',[C('pest.s1','害虫；有害小动物','The farmer covered the seedlings with netting after a pest destroyed the first row of leaves.','害虫毁掉第一排叶片后，农民给幼苗盖上了网。','The farmer covered the seedlings / after a pest destroyed / the first row of leaves.','pest.s1 指危害作物、食物或住所的昆虫或小动物。','害虫啃食幼苗叶片。'),C('pest.s2','讨厌鬼；不断烦人的人','The child called his brother a pest because he kept interrupting the video lesson.','孩子说哥哥是个讨厌鬼，因为他不断打断视频课。','The child called his brother a pest / because he kept interrupting / the video lesson.','pest.s2 可口语指持续打扰别人的人。','弟弟不断打断课程。')],M('The pest damaged the seedlings, but the farmer said it was harmless and had not touched any leaves.','The pest damaged the seedlings by chewing through their first row of leaves.','已经毁坏幼苗的害虫不能同时说完全无害且没有触碰叶片。','meaning'),[q('What did the pest do to the seedlings?','destroyed the first row of leaves','helped them grow taller','covered them with protective netting','害虫毁坏了第一排叶片。',1,'context'),q('Why did the child call his brother a pest?','he kept interrupting the lesson','he repaired the farm netting','he asked the authority to change a rule','哥哥不断打断课程，令人烦扰。',2,'context'),q('Which creature could be called a pest in a garden?','a beetle destroying young plants','a bee pollinating flowers without causing damage','a pet dog sleeping indoors','毁坏幼苗的甲虫属于害虫。',1,'meaning'),q('Which origin is documented for pest?','French peste and Latin pestis','Greek petalon','French petite','pest 经法语源自拉丁语 pestis。',1,'word-formation')]);
P('pester','Pester came through Middle English from Anglo-French pestour and is related to pest; it means keep asking someone for something in an irritating way.',C('pester.s1','纠缠；不断烦扰索求','The reporters pestered the spokesperson for an exact release date until she asked them to submit questions in writing.','记者们不断追问发言人确切发布日期，直到她请他们把问题书面提交。','The reporters pestered the spokesperson / for an exact release date / until she asked for written questions.','pester 指以令人厌烦的方式不断询问或索要。','同一发布日期被一再追问。'),M('The reporters pestered the spokesperson by asking once, accepting her answer, and never contacting her again.','The reporters pestered the spokesperson by repeatedly demanding an exact release date.','只问一次并接受回答，不符合反复纠缠的含义。','meaning'),[q('What did the reporters keep asking for?','an exact release date','a pet name for the spokesperson','a botanical name for a leaf stalk','记者们反复追问发布日期。'),q('What does pester mean?','keep asking in an annoying way','make someone expect the worst','turn organic matter into stone','pester 指不断烦扰地索问。',1,'meaning'),q('Which action would pester a neighbor?','repeatedly demanding a borrowed tool after being asked to stop','returning the tool at the agreed time','leaving one polite note about a repair','在被要求停止后仍反复索要工具属于纠缠。',1,'context'),q('Which related word names an annoying person or creature?','pest','petal','pessimism','pest 可指令人烦扰的人或有害生物。',1,'word-formation')]);
P('pesticide','Pesticide combines pest with -cide, “killer,” from Latin caedere; it names a chemical used to kill harmful insects or, more broadly in agriculture, pests and plant diseases.',[C('pesticide.s1','杀虫剂','The greenhouse worker applied a pesticide to the tomato plants after whiteflies appeared beneath the leaves.','温室工人发现叶片下有粉虱后，给番茄植株喷了杀虫剂。','The worker applied a pesticide / after whiteflies appeared / beneath the tomato leaves.','pesticide.s1 指用于杀死危害植物或健康的昆虫的化学品。','杀虫剂针对叶片下的粉虱。'),C('pesticide.s2','农用杀害物化学品','The farm’s pesticide treatment targeted both insect pests and a fungal disease affecting the stored seed.','农场使用的农药处理既针对害虫，也针对影响储存种子的真菌病害。','The farm’s pesticide treatment targeted / insect pests and a fungal disease / in the stored seed.','pesticide.s2 在农业语境中可泛指用于消灭害虫或植物病害的化学品。','农药方案同时处理昆虫和植物病害。')],M('The pesticide protected the tomatoes from whiteflies by attracting more whiteflies to eat the leaves.','The pesticide protected the tomatoes by killing the whiteflies attacking the leaves.','杀虫剂防治害虫，不会通过引来更多害虫保护作物。','meaning'),[q('Why did the greenhouse worker use pesticide?','whiteflies were feeding beneath the tomato leaves','the tomato flowers needed more petals','the seed labels were difficult to read','工人发现粉虱后使用杀虫剂。',1,'context'),q('What does pesticide mean in the seed-treatment example?','an agricultural chemical used against pests or plant disease','a fertilizer made only to add water','a name for a plant’s leaf stalk','该处 pesticide 泛指防治害虫或植物病害的农用化学品。',2,'meaning'),q('Which word-forming element in pesticide means “killer”?','-cide','-ist','-ous','-cide 表示“杀灭者、杀灭剂”。',1,'word-formation'),q('Which substance is a pesticide?','a chemical applied to kill insects damaging a crop','a harmless label tied to a seed packet','a chemical that only adds color to a flower','用于杀死危害作物昆虫的化学品是杀虫剂。',1,'meaning')]);
P('pestilence','Pestilence came through French from Latin pestilentia, “plague or contagious disease”; it means a deadly disease that spreads widely among people.',C('pestilence.s1','瘟疫；致命传染病','The old chronicle records a pestilence that emptied villages and killed thousands across the region.','旧编年史记载，一场瘟疫使村庄空无一人，并造成该地区数千人死亡。','The chronicle records a pestilence / that emptied villages / and killed thousands.','pestilence 指广泛传播、造成大量死亡的疾病。','疾病跨地区传播并造成大规模死亡。'),M('The chronicle called it a pestilence, although the brief local rash affected two people and caused no deaths.','The chronicle called it a pestilence because the disease spread widely and killed thousands.','局部、轻微且没有死亡的皮疹不符合大范围致命瘟疫的含义。','meaning'),[q('What effects did the recorded pestilence have?','it emptied villages and killed thousands','it caused one harmless itch','it improved the harvest','史料中的瘟疫使村庄空置并造成大量死亡。'),q('What does pestilence mean?','a disease that spreads widely and kills many people','any small annoyance that interrupts a task','a chemical used to treat garden insects','pestilence 指广泛传播并造成大量死亡的疾病。',1,'meaning'),q('Which event could be called a pestilence?','a deadly epidemic spreading across several towns','a mild cold affecting one person for a day','a single insect damaging one leaf','致命疾病蔓延多个城镇可称为 pestilence。',1,'context'),q('Which Latin noun is the source of pestilence?','pestilentia','petalon','pessimus','pestilence 源于拉丁语 pestilentia。',1,'word-formation')]);
P('pestilent','Pestilent comes from Latin pestilent-, the stem of pestilens, “plague-ridden”; it describes something likely to cause disease, death, or serious harm.',C('pestilent.s1','致病的；有害的','Officials closed the pestilent well after tests found bacteria that could cause severe illness.','检测发现井中有可致重病的细菌后，官员关闭了这口有害的井。','Officials closed the pestilent well / after tests found bacteria / that could cause severe illness.','pestilent 形容容易造成疾病、死亡或严重危害的事物。','井水受到致病细菌污染。'),M('The officials called the well pestilent even though tests proved its water safe and free of disease-causing organisms.','The officials called the well pestilent because its water contained bacteria that could cause serious illness.','水安全且无致病微生物，与“可能致病”相矛盾。','meaning'),[q('Why did officials close the well?','tests found bacteria that could cause severe illness','the water had a pleasant taste','a petition asked for a new name','检测发现可能致病的细菌。'),q('What does pestilent describe?','likely to cause disease or serious harm','likely to persuade a committee','likely to produce a new flower petal','pestilent 指可能造成疾病或严重危害的。',1,'meaning'),q('Which source is pestilent?','a contaminated well linked to severe illness','a tested clean spring','a harmless petal on a garden flower','导致重病的污染水源具有危害性。',1,'context'),q('Which noun is closely related to pestilent?','pestilence','pessimist','petrifaction','pestilent 与 pestilence 同源。',1,'word-formation')]);
P('pestilential','Pestilential is formed from pestilence or pestilent with -ial; it means plague-like or extremely unpleasant and harmful.',C('pestilential.s1','瘟疫般的；有害难闻的','The pestilential smoke from the illegal dump forced nearby residents to leave until the fire was controlled.','非法垃圾场冒出的有害浓烟迫使附近居民撤离，直到火势得到控制。','The pestilential smoke / forced nearby residents to leave / until the fire was controlled.','pestilential 可形容像瘟疫一样危害健康的，也可泛指极其令人不快、有害的事物。','有毒浓烟迫使居民撤离。'),M('The report described the air as pestilential even though tests found it clean, harmless, and odorless.','The report described the air as pestilential because the smoke was toxic and forced residents to evacuate.','空气洁净无害与“瘟疫般有害”不符。','meaning'),[q('What did the pestilential smoke cause?','nearby residents had to leave','residents received a pet name','the dump produced flower petals','有害烟雾迫使附近居民撤离。'),q('What does pestilential mean here?','extremely harmful or plague-like','mildly inconvenient but harmless','clear enough to read easily','pestilential 指严重有害或像瘟疫般的。',1,'meaning'),q('Which condition is pestilential?','toxic fumes making a neighborhood unsafe','a quiet room with clean air','a minor spelling error on a label','让社区不安全的有毒烟雾是严重有害的。',1,'context'),q('Which word family is pestilential part of?','pestilence','persuasion','petrify','pestilential 属于 pestilence 同词族。',1,'word-formation')]);
P('pet','Pet is first recorded in Scottish and northern English dialect for a favored child or animal; its deeper origin is uncertain. It can mean a companion animal, a favorite person, or stroke an animal gently.',[C('pet.s1','宠物；伴侣动物','The shelter matched each rescued pet with a family prepared to provide daily care.','收容所为每只获救的宠物匹配了一户愿意日常照料的家庭。','The shelter matched each rescued pet / with a family / prepared to provide daily care.','pet.s1 指与人共同生活、作为伴侣的动物。','动物被安置到家庭中共同生活。'),C('pet.s2','宠儿；最受偏爱的人','The coach’s pet was not always the most talented player, but received extra chances to lead the team.','教练的宠儿不总是最有天赋的球员，却获得更多带队机会。','The coach’s pet was not always the most talented / but received extra chances / to lead the team.','pet.s2 可指受某人特别偏爱的人。','某球员因偏爱而获得更多机会。'),C('pet.s3','轻轻抚摸动物','The child asked before she petted the neighbor’s shy cat, then stroked it gently under the chin.','孩子先征得同意才抚摸邻居怕生的猫，然后轻轻摸它的下巴。','The child asked before she petted the cat / then stroked it gently / under the chin.','pet.s3 作动词，指友好地轻轻抚摸动物。','孩子温和地抚摸小猫。')],M('The child petted the frightened cat by pulling its tail and squeezing it when it tried to move away.','The child petted the cat gently after asking and let it move away when it wished.','拉扯尾巴、强行抱紧不是友好轻抚，可能伤害动物。','meaning'),[q('What happened to the rescued pets?','they were matched with families for daily care','they were sent to a pest-control company','they were turned into stone','收容所为宠物寻找照料家庭。',1,'context'),q('Who is called the coach’s pet?','the person receiving special favor','the most troublesome insect in the stadium','the coach’s companion animal','教练特别偏爱的人可称为 coach’s pet。',2,'meaning'),q('What did the child do when she petted the cat?','gently stroked it after asking','pulled its tail to stop it moving','left it outside without care','pet 作动词表示友好轻抚动物。',3,'context'),q('What is known about the deeper origin of pet?','it is uncertain','it definitely comes from Latin petra','it is formed from pest and -cide','pet 的更早词源尚不确定。',1,'word-formation')]);
P('pet name','Pet name combines pet in its sense “favored or cherished” with name; it means an affectionate special name used for someone one loves.',C('pet name.s1','昵称；爱称','At home, the grandparents still call their grandson “Little Fox,” the pet name they gave him as a toddler.','在家里，祖父母仍称孙子为“小狐狸”，这是他幼儿时期得到的爱称。','At home / the grandparents call their grandson “Little Fox” / the pet name they gave him as a toddler.','pet name 指亲友之间表达亲昵的特别称呼。','祖父母使用童年时取的爱称。'),M('“Little Fox” was a pet name because the grandparents used it on a public tax form as the child’s legal surname.','“Little Fox” was a pet name because the grandparents used it affectionately at home.','昵称是亲昵称呼，不是正式法律姓氏。','meaning'),[q('Who uses “Little Fox” as the pet name?','the grandparents','the tax office','the pest-control workers','祖父母在家里使用这个爱称。'),q('What is a pet name?','an affectionate special name for someone','the scientific name of a plant stalk','a name given to a dangerous chemical','pet name 指亲昵的特别称呼。',1,'meaning'),q('Which is a pet name?','a family’s affectionate “Sunny” for their child','a product’s registration number','the legal title on a court petition','家人给孩子取的亲昵称呼属于 pet name。',1,'context'),q('Which sense of pet contributes to pet name?','favored or cherished','likely to cause an epidemic','turned into stone','pet name 中 pet 表示受宠爱、珍视的。',1,'word-formation')]);
P('pet peeve','Pet peeve combines pet, “especially favored or personal,” with peeve, “annoyance”; the phrase, recorded by the early 20th century, means a particular recurring irritation.',C('pet peeve.s1','特别令人恼火的事；心头烦事','Her pet peeve is people who leave shopping carts in accessible parking spaces.','她特别讨厌有人把购物车留在无障碍停车位上。','Her pet peeve is people / who leave shopping carts / in accessible parking spaces.','pet peeve 指某人尤其介意、经常被惹恼的一种小事。','反复遇到购物车挡住无障碍车位。'),M('His pet peeve was a one-time delay that did not bother him and that he never remembered afterward.','His pet peeve was the recurring habit of colleagues leaving noisy alerts on during meetings.','既不令人烦恼也不反复出现的事件不是 pet peeve。','meaning'),[q('What is her pet peeve?','carts left in accessible parking spaces','the name of a favorite pet','the color of a flower’s petals','她最介意购物车挡住无障碍车位。'),q('What does pet peeve mean?','a particular recurring source of irritation','a cherished nickname for a child','a chemical used to kill insects','pet peeve 指某人特别烦恼的一件反复发生的事。',1,'meaning'),q('Which is a pet peeve?','the repeated clicking of a pen during every meeting','one useful reminder sent once','a pet cat sleeping quietly','反复出现的会议敲笔声会成为令人恼火的小事。',1,'context'),q('What does peeve mean in the phrase?','an annoyance or irritation','a companion animal','a formal request to a court','peeve 在词组中表示令人恼火的事。',1,'meaning')]);
P('petal','Petal came through Modern Latin from Greek petalon, “leaf or broad flat thing”; it names one of the often colored parts surrounding a flower’s center.',C('petal.s1','花瓣','A pale pink petal fell onto the table when the florist trimmed the open rose.','花店修剪盛开的玫瑰时，一片浅粉色花瓣落在桌上。','A pale pink petal fell / when the florist trimmed / the open rose.','petal 是围绕花心的柔软部分，常有鲜艳颜色。','玫瑰上脱落的是单片花瓣。'),M('The florist called the flower’s slender leaf stalk a petal and its colored part the petiole.','The florist called the colored part a petal and the slender leaf stalk a petiole.','petal 是花瓣，petiole 是叶柄，两者名称互换错误。','meaning'),[q('What fell onto the table?','a pink piece surrounding the rose’s center','the stalk connecting a leaf to its stem','a chemical label','落下的是玫瑰花瓣。'),q('What is a petal?','a often-colored part of a flower’s corolla','the slender stalk of a leaf','a tiny insect that damages flowers','petal 指花朵中围绕花心的部分。',1,'meaning'),q('Which item is a petal?','one of the soft colored parts of a tulip','the narrow stalk joining a leaf to a stem','the root of a chemical compound','郁金香柔软有色的组成部分是花瓣。',1,'context'),q('Which Greek word is the source of petal?','petalon, “leaf or broad flat thing”','pessimus, “worst”','petere, “to ask”','petal 源自希腊语 petalon。',1,'word-formation')]);
P('petiole','Petiole entered English from French pétiole and Late Latin petiolus, a form meaning “little foot”; botanically, it is the slender stalk attaching a leaf blade to a stem.',C('petiole.s1','叶柄','The botanist traced the damaged petiole from the leaf blade to the main stem.','植物学家沿着受损的叶柄从叶片追踪到主茎。','The botanist traced the damaged petiole / from the leaf blade / to the main stem.','petiole 是连接叶片与茎的细柄。','叶柄连接叶片和主茎。'),M('The botanist identified the broad, flat leaf blade as the petiole and the thin connecting stalk as the petal.','The botanist identified the thin stalk connecting the leaf blade to the stem as the petiole.','petiole 指叶柄；花瓣是 petal，叶片本身也不是叶柄。','meaning'),[q('Which part did the botanist trace?','the stalk linking the leaf to the stem','a colored part around a flower’s center','the plant’s root tip','植物学家追踪的是连接叶片和茎的叶柄。'),q('What is a petiole?','the slender stalk of a leaf','the broad colored part of a flower','a pest that eats plant leaves','petiole 指叶柄。',1,'meaning'),q('Which description points to a petiole?','the narrow connector between a leaf blade and its stem','one soft segment of a blossom','the outer covering of a seed','叶柄连接叶片与茎。',1,'context'),q('What does the Latin source petiolus literally suggest?','a little foot','the worst outcome','a formal request','petiolus 是表示“小脚”的词形。',1,'word-formation')]);
P('petite','Petite came from French petite, the feminine form of petit, “small”; it commonly describes a woman who is short and delicately built.',C('petite.s1','娇小的；身材小巧的','The petite violinist adjusted the shoulder rest before lifting the full-size instrument.','这位娇小的小提琴手在举起标准尺寸的乐器前调整了肩托。','The petite violinist adjusted the shoulder rest / before lifting / the full-size instrument.','petite 常形容身材小巧纤细的人，尤用于女性。','人物身材娇小而小提琴是标准尺寸。'),M('The petite violinist was described as petite because she was exceptionally tall and broadly built.','The petite violinist was described as petite because she was short and delicately built.','身材高大魁梧与 petite 的“小巧纤细”含义相反。','meaning'),[q('How is the violinist described?','short and delicately built','tall and heavily built','likely to spread disease','petite 指她身材小巧纤细。'),q('What does petite usually describe?','a short, delicately built woman','a very large building','a person who expects the worst','petite 常形容身材娇小的女性。',1,'meaning'),q('Which person could be described as petite?','a short, slender dancer','a towering basketball player with a broad build','a pest-control chemical','矮小纤细的舞者可称 petite。',1,'context'),q('Which French word is the source of petite?','petit, “small”','peste, “plague”','pessimus, “worst”','petite 源于法语 petit。',1,'word-formation')]);
P('petition','Petition comes through Old French from Latin petitionem, from petere, “seek or ask”; it can be a group’s written request, the formal act of asking, or an application to a court.',[C('petition.s1','请愿书；联名请求','Residents delivered a petition signed by 640 households asking the council to keep the library open at night.','居民递交了一份由 640 户签署的请愿书，请求市议会让图书馆夜间继续开放。','Residents delivered a petition / signed by 640 households / asking the council to keep the library open.','petition.s1 是提交给当局、通常由多人签署的书面请求。','多人联署向市议会提出要求。'),C('petition.s2','正式请求；向当局请愿','The tenants petitioned the housing authority to repair the broken elevator before winter.','租户们正式请求住房主管部门在冬季前修好坏掉的电梯。','The tenants petitioned the housing authority / to repair the elevator / before winter.','petition.s2 作动词，指正式向主管部门请求改变或提供帮助。','租户向主管部门正式提出维修请求。'),C('petition.s3','向法院提出申请','The company petitioned the court for permission to reorganize its debts under supervision.','公司向法院申请在监督下重组债务。','The company petitioned the court / for permission / to reorganize its debts.','petition.s3 指向法院提出正式法律申请。','申请交给法院并涉及债务重组。')],M('The residents filed a petition by making no written request, collecting no signatures, and asking the council for nothing.','The residents filed a petition signed by local households asking the council to keep the library open.','没有书面请求、签名或请求内容，就没有提交 petition。','meaning'),[q('What did residents ask the council to do?','keep the library open at night','rename the court','remove every pet from the neighborhood','居民请愿让图书馆夜间继续开放。',1,'context'),q('How did the tenants use petition as a verb?','they formally asked the housing authority for repairs','they signed an animal-care contract','they read the authority’s notice carefully','租户正式向主管部门提出维修请求。',2,'context'),q('Which action is a court petition?','asking a court for permission to reorganize company debts','asking a neighbor once to borrow a pen','writing a private pet name on a card','向法院申请债务重组属于法律申请。',3,'context'),q('Which Latin verb underlies petition?','petere, “seek or ask”','petere, “turn to stone”','pestis, “breathe through”','petition 源自表示“寻求、请求”的 petere。',1,'word-formation')]);
P('petrifaction','Petrifaction is formed from petrify with -faction, naming either the geological conversion of organic material into stone or a state of frozen fear.',[C('petrifaction.s1','石化；石化形成物','The museum’s petrifaction specimen preserved the shape of ancient wood after minerals replaced its structure.','博物馆的石化标本保留了古木的形状，矿物已取代其原有结构。','The specimen preserved the shape of ancient wood / after minerals replaced / its original structure.','petrifaction.s1 指有机物转化成石头的过程或产物。','木材的结构被矿物取代。'),C('petrifaction.s2','吓呆；僵住','She watched in petrifaction as the loose balcony railing gave way beneath the ladder.','梯子下方松动的阳台栏杆脱落时，她吓得僵在原地。','She watched in petrifaction / as the loose railing / gave way beneath the ladder.','petrifaction.s2 是因恐惧或震惊而僵住的状态。','突发危险让她动弹不得。')],M('Minerals replaced the wood in the fossil, but the report called the process a petrifaction that left the material entirely unchanged.','Minerals replaced the wood in the fossil through petrifaction, turning the organic structure to stone.','材料结构完全未变与矿物替代并石化相矛盾。','meaning'),[q('What happened to the ancient wood in the specimen?','minerals replaced its structure and preserved its shape','it was gently stroked like a pet','it was turned into a leaf stalk','矿物取代木质结构而保留形状，形成石化标本。',1,'context'),q('What does petrifaction mean in the balcony scene?','being frozen with fear or shock','a written request to a court','a chemical made from petroleum','她因突发危险而吓得僵住。',2,'meaning'),q('Which event causes petrifaction in the second sense?','a person becomes motionless after a sudden frightening event','wood slowly becomes mineralized over geological time','someone asks an authority to repair a road','突发惊吓使人僵住属于第二义。',2,'context'),q('Which verb is the base of petrifaction?','petrify','pervade','pester','petrifaction 由 petrify 派生。',1,'word-formation')]);
P('petrify','Petrify came through French and Latin forms based on Greek petra, “rock”; it means turn organic material to stone or frighten a person into immobility.',[C('petrify.s1','使石化','Over geological time, mineral-rich water can petrify wood while preserving its growth rings.','经过漫长地质时间，富含矿物质的水可以使木材石化，同时保留年轮。','Over geological time / mineral-rich water can petrify wood / while preserving its growth rings.','petrify.s1 指经过漫长过程把木材或生物组织转化成石头。','矿物质逐步取代木材结构。'),C('petrify.s2','使吓呆；使僵住','The sudden crack of ice beneath the hikers petrified them for a moment before they stepped back.','冰层在徒步者脚下突然开裂，吓得他们一时僵住，随后才退开。','The sudden crack of ice / petrified the hikers / before they stepped back.','petrify.s2 表示吓到某人动弹不得或说不出话。','冰面突然开裂造成短暂惊吓。')],M('The sudden crack petrified the hikers, so they calmly ignored it and kept walking forward without stopping.','The sudden crack petrified the hikers, leaving them frozen for a moment before they moved back.','若他们完全镇定并继续前进，就没有被吓得僵住。','meaning'),[q('What can mineral-rich water do to wood over time?','petrify it while preserving growth rings','pester it until it becomes a pet','persuade it to grow a petal','矿物质可使木材逐渐石化并保留年轮。',1,'context'),q('What happened when the ice cracked?','the hikers froze briefly with fear','the hikers filed a court application','the hikers became pessimistic about a petition','徒步者被突发声响吓得短暂僵住。',2,'context'),q('Which sentence uses petrify in the “frighten” sense?','The unexpected siren petrified the child.','Minerals petrified the buried tree trunk.','The council heard the petition.','警笛把孩子吓呆，使用其“使僵住”义。',2,'meaning'),q('Which source element means “rock”?','Greek petra','Latin pessimus','Latin petere','petrify 的词源包含表示“岩石”的 petra。',1,'word-formation')]);
P('petrochemical','Petrochemical combines petro-, from petroleum, with chemical; as a noun it is a chemical product made from oil or natural gas, and as an adjective it relates to such products.',[C('petrochemical.s1','石油化工产品','The plant converts natural gas into a petrochemical used to make packaging resin.','这家工厂把天然气转化为一种用于制造包装树脂的石油化工产品。','The plant converts natural gas / into a petrochemical / used to make packaging resin.','petrochemical.s1 指由石油或天然气制成的化学产品。','天然气经加工成为包装树脂原料。'),C('petrochemical.s2','石油化学的','The engineers inspected a petrochemical pipeline carrying feedstock from the refinery to the plastics facility.','工程师检查了一条从炼油厂向塑料厂输送原料的石油化学管道。','The engineers inspected a petrochemical pipeline / carrying feedstock / from the refinery to the plastics facility.','petrochemical.s2 作形容词，表示与石油来源化学品有关。','管道输送炼油厂生产的化工原料。')],M('The plant called its natural-gas-derived resin a petrochemical even though the material contained no chemical product and came only from a flower.','The plant called its natural-gas-derived resin a petrochemical because it was made from fossil-fuel feedstock.','由天然气原料制成的化学产品确实是 petrochemical；“只来自花且非化学品”与事实相反。','meaning'),[q('What does the plant make from natural gas?','a chemical used to produce packaging resin','a petal used to decorate a package','a court petition about the refinery','工厂把天然气制成包装树脂的化学原料。',1,'context'),q('What does petrochemical mean as a noun?','a chemical product made from oil or natural gas','any naturally grown flower petal','a chemical used only to kill insects','名词 petrochemical 指由石油或天然气制成的化学产品。',1,'meaning'),q('Which pipeline is petrochemical?','one carrying refinery feedstock to a plastics plant','one carrying clean drinking water to homes','one transporting flower seeds to a greenhouse','输送炼油化工原料的管道与石化有关。',2,'context'),q('What does the petro- element refer to in this word?','petroleum or petroleum-derived material','a favorite companion animal','the worst possible outcome','petro- 在此指石油来源。',1,'word-formation')]);
})();
